(window.FREALLY_I18N = window.FREALLY_I18N || {})["hi"] = {"hero.headline":"<span class=\"hl-muted\">असली हाथों को अपना संगीत बजाते देखें।</span> <span class=\"cycle\" data-cycle=\"hero.cycle\" data-words=\"Then drag it into your DAW.|Read every note.|Learn how it is played.\">फिर इसे अपने DAW में खींचें।</span>","hero.cycle":"फिर इसे अपने DAW में खींचें।|हर नोट पढ़ें।|सीखें कि इसे कैसे बजाया जाता है।","hero.sub":"कॉर्ड्स, एक धुन, एक बेसलाइन और एक काउंटरमेलोडी, किसी भी शैली में लिखे गए, शीट म्यूज़िक के रूप में दिखाए गए और यथार्थवादी हाथों द्वारा यथार्थवादी वाद्यों पर बजाए गए, पियानो और गिटार से लेकर पूरे बैंड तक। साथ में संगीत के पाठ, जो आपको इसे ख़ुद बजाना, लिखना और अरेंज करना सिखाते हैं। ऑफ़लाइन और 100% AI-मुक्त।","hero.chipStandalone":"स्टैंडअलोन","what.title":"यह क्या है","what.p1":"कॉर्ड जनरेटर इस्तेमाल करने वाले ज़्यादातर लोग कभी नहीं देखते कि उसके हिस्से कैसे बजाए जाएँगे, और कोई वाद्य सीखने वाले ज़्यादातर लोग कभी किसी वादक के हाथ क़रीब से नहीं देखते। Handscore आपको दोनों दिखाता है।","what.p2":"कोई जॉनर, कलाकार या प्रोड्यूसर चुनें और Handscore उस शैली में चार हिस्से लिखता है: कॉर्ड्स, एक धुन, एक बेसलाइन और एक काउंटरमेलोडी। वे वाद्य के म्यूज़िक स्टैंड पर शीट म्यूज़िक के पन्नों के रूप में दिखते हैं, और यथार्थवादी हाथ उन्हें वैसे ही बजाते हैं जैसे उस वाद्य का कोई वादक बजाता: हर उंगली उसी कुंजी पर जिसे कोई पियानोवादक इस्तेमाल करता, हर फ़्रेट और स्ट्रम वैसा ही जैसा कोई गिटारवादक करता। पहले पियानो आते हैं, फिर गिटार और बास गिटार, और उनके बाद वाद्यों का हर परिवार, पूरे बैंड तक।","what.p3":"हर नोट वहीं दिखाया जाता है जहाँ वह बजाया जाता है, और पियानो की हर कुंजी का नाम उसके सामने वाले हिस्से पर लिखा है, ताकि आप ठीक-ठीक देख सकें कि क्या बज रहा है। जब कोई हिस्सा सही लगे, तो उसे उसकी शीट से सीधे अपने DAW के किसी ट्रैक पर खींच लें।","what.p4":"और यह सिखाता भी है। पाठ पहले दिन पियानो पर शुरू होते हैं, आपको बजाते हुए सुनते हैं और आपके सही बजाने पर आगे बढ़ते हैं, फिर शीट म्यूज़िक पढ़ना, रिदम, ईयर ट्रेनिंग, थ्योरी, सॉन्गराइटिंग और गीत के बोल, गाने का अरेंजमेंट, मिक्सिंग, फ़िंगर ड्रमिंग, ड्रम किट, गिटार, क्लासिकल गिटार और बेस तक जाते हैं।","inside.title":"यह क्या करेगा","inside.instruments.title":"वाद्यों का हर परिवार","inside.instruments.body":"पहले चार असली पियानो, फिर एक पैड कंट्रोलर और एक ड्रम किट, गिटार और बास गिटार; उनके बाद ऑर्गन, मैलेट वाद्य, हार्प, गज़ से बजने वाले तार वाद्य, वुडविंड और ब्रास, एक-एक परिवार करके, पूरे बैंड तक।","inside.hands.title":"यथार्थवादी हाथ","inside.hands.body":"दो हाथ जो हर नोट वैसे ही बजाते हैं जैसे उस वाद्य का कोई वादक बजाता: वही उंगली जो कोई पियानोवादक चुनता, वही फ़्रेट और स्ट्रोक जो कोई गिटारवादक इस्तेमाल करता।","inside.lessons.title":"संगीत के पाठ","inside.lessons.body":"पियानो, गिटार और बेस पर आपके पहले नोट्स से लेकर शीट म्यूज़िक पढ़ना, रिदम, ईयर ट्रेनिंग, थ्योरी, सॉन्गराइटिंग और गीत के बोल, गाने का अरेंजमेंट और मिक्सिंग तक के कोर्स। ये आपको बजाते हुए सुनते हैं, और जब आप ज़ोर से पढ़ें स्विच चालू करते हैं तो हर पाठ आपको पढ़कर सुनाते हैं।","inside.drums.title":"ड्रम","inside.drums.body":"एक ड्रम मशीन जिसके पैडों पर आपके अपने सैंपल हों और एक स्टेप सीक्वेंसर, एक पैड कंट्रोलर जिसके पैड हर हिट पर रोशन होते हैं, और एक ड्रम किट जिसे एक ड्रमर के हाथ और पैर बजाते हैं, साथ में फ़िंगर ड्रमिंग और ड्रम किट के कोर्स।","inside.sheets.title":"शीट म्यूज़िक के चार पन्ने","inside.sheets.body":"कॉर्ड्स, धुन, काउंटरमेलोडी और बास, हर एक अपनी अलग शीट पर, और हर नोट बजते समय रोशन होता है।","inside.styles.title":"हर शैली जिसे Freally MIDI Master जानता है","inside.styles.body":"73 जॉनर, 1,507 कलाकार और 833 प्रोड्यूसर, उन्हीं नियम-आधारित जनरेटरों से।","inside.drag.title":"MIDI खींचें","inside.drag.body":"एक बार में एक हिस्सा या चारों एक साथ, शीट्स से सीधे आपके DAW में खींचे गए, या MIDI फ़ाइल के रूप में या शीट्स की PDF के रूप में सहेजे गए।","inside.views.title":"सामने, ऊपर और बगल के व्यू","inside.views.body":"संगीत बजते समय इनके बीच बदलें; शीट्स पढ़ने लायक बने रहने के लिए घूम जाती हैं और हाथ कभी कोई नोट नहीं चूकते।","inside.daw.title":"किसी भी DAW में","inside.daw.body":"CLAP, VST3 और AU, साथ ही एक स्टैंडअलोन ऐप। Windows, macOS और Linux।","inside.offline.title":"ऑफ़लाइन, बिना AI","inside.offline.body":"कोई खाता नहीं, कोई टेलीमेट्री नहीं, कोई नेटवर्क नहीं, कोई मॉडल नहीं। हर हिस्सा, फ़िंगरिंग और हरकत नियमों से आती है, जिसे केवल वादा नहीं बल्कि एक बिल्ड गेट लागू करवाता है।","ladder.title":"1.0 की ओर रास्ता, और आगे 2.0 तक","ladder.intro":"हर संस्करण के लिए एक पंक्ति। पाठ, फ़िंगर ड्रमिंग, ड्रम मशीन और ड्रम किट, गिटार और बास गिटार 1.0 से पहले आते हैं। उसके बाद, हर संस्करण वाद्यों का एक नया परिवार लाता है, जिन्हें यथार्थवादी हाथ वैसे बजाते हैं जैसे कोई शिक्षक आपको दिखाता।","ladder.rung.v0.1.0":"नींव: प्लगइन CLAP, VST3 और AU के रूप में और स्टैंडअलोन ऐप के रूप में लोड होता है, अपने लाइसेंस की स्वीकृति माँगता है, और 88 कुंजियों वाले कीबोर्ड पर खुलता है जिसकी हर कुंजी का नाम लिखा है।","ladder.rung.v0.2.0":"असली पियानो: ग्रैंड, अकूस्टिक, अपराइट और होंकी-टोंक, बजते समय उनकी कुंजियाँ हिलती और बजती हैं।","ladder.rung.v0.3.0":"कीबोर्ड पर यथार्थवादी हाथ, हर नोट की फ़िंगरिंग वैसे ही करते हुए जैसे कोई पियानोवादक करता, साथ में सीखने के लिए बासठ पब्लिक-डोमेन क्लासिक्स और सुनते हुए उनमें आगे-पीछे जाने के लिए एक ट्रांसपोर्ट।","ladder.rung.v0.4.0":"किसी भी शैली में जनरेट करें, चारों शीट्स को रोशन होते हुए पढ़ें, और MIDI को अपने DAW में खींचें।","ladder.rung.v0.5.0":"ऊपर और बगल के व्यू, शीट्स पियानो पर सपाट रखी हुई, और व्यू के बीच सहज बदलाव।","ladder.rung.lessons-1":"पहले दिन से पाठ: एक पियानो कोर्स जो आपको बजाते हुए सुनता है और आपके सही बजाने पर आगे बढ़ता है, और एक ज़ोर से पढ़ें स्विच जो हर पाठ आपको पढ़कर सुनाता है, बोले जाते समय हर शब्द रोशन करते हुए।","ladder.rung.mixer":"हर हिस्से के लिए एक मिक्सर, फ़ेडर, पैन, EQ, इफ़ेक्ट्स और कंप्रेशन के साथ, और खींचने पर भी मिक्स बना रहता है।","ladder.rung.song-view":"सॉन्ग व्यू: सेक्शन-दर-सेक्शन ख़ुद एक पूरा गाना बनाएँ, या किसी कलाकार या जॉनर के अरेंजमेंट से शुरुआत करें, फिर उसे बजते हुए देखें और अपने DAW में खींच लें।","ladder.rung.lessons-2":"और कोर्स: शीट म्यूज़िक पढ़ना, रिदम, ईयर ट्रेनिंग, Nashville Number System के साथ म्यूज़िक थ्योरी, सॉन्गराइटिंग और गीत के बोल, अरेंजिंग और मिक्सिंग।","ladder.rung.finger-drumming":"एक पैड कंट्रोलर पर फ़िंगर ड्रमिंग, जिसके पैड हर हिट पर रोशन होते हैं, पहली बीट से लेकर पूरे ग्रूव तक।","ladder.rung.drum-kit":"एक ड्रम किट, जिसे वैसे ही सेट किया और बजाया गया है जैसे कोई पेशेवर ड्रमर करता, और उसके साथ एक ड्रम मशीन, एक ही स्विच से यह चुनने के लिए कि आपके ड्रम कौन बजाए।","ladder.rung.live-listening":"लाइव लिसनिंग: माइक्रोफ़ोन या इंस्ट्रूमेंट केबल के ज़रिए कोई असली वाद्य बजाएँ या गाएँ, और पाठ उसे सुनते हैं, ट्यूनर और लेटेंसी कैलिब्रेशन के साथ।","ladder.rung.guitars":"गिटार: स्टील-स्ट्रिंग, नायलॉन, इलेक्ट्रिक और म्यूटेड, एक गिटारवादक के हाथों से फ़्रेट, पिक और स्ट्रम किए गए, शीटों पर TAB और दो गिटार कोर्स के साथ।","ladder.rung.bass":"बेस: चार या पाँच तारों वाले दो बेस गिटार और एक डबल बेस, एक बेसवादक के हाथों से उंगलियों से बजाए गए, स्लैप और पॉप किए गए, 808 की स्लाइड तार के साथ फिसलती हुई, एक बेस पाठ्यक्रम के साथ; और Handscore के अपने एम्प से बजते दो रॉक गिटार।","ladder.rung.own-audio":"आपका अपना ऑडियो और MIDI, हिस्सों में पढ़ा गया और हाथों द्वारा बजाया गया।","ladder.rung.classics":"क्लासिक्स: देखने और सुनने के लिए पब्लिक-डोमेन धुनें।","ladder.rung.realism":"यथार्थवाद का दौर: रोशनी, मटीरियल और हरकत, फ़िल्माए गए वादन की कसौटी पर।","ladder.rung.finish":"अंतिम रूप: सेटिंग्स, हर जगह अठारह भाषाएँ, सुगम्यता और मैनुअल।","ladder.rung.v1.0.0-beta.1":"अपडेट सूचनाएँ और ट्रायल तथा पेड संस्करण।","ladder.rung.v1.0.0":"पहली सार्वजनिक रिलीज़।","ladder.rung.v1.1.0":"इलेक्ट्रिक पियानो और ऑर्गन, ऑर्गन बेसलाइन के लिए पेडलबोर्ड के साथ।","ladder.rung.v1.2.0":"हार्प्सीकॉर्ड, क्लैविनेट, चेलेस्टा और खिलौना पियानो; यूकुलेले, बैंजो और मैंडोलिन।","ladder.rung.v1.3.0":"मैलेट वाद्य: ज़ाइलोफ़ोन, मरिम्बा, वाइब्राफ़ोन और ग्लॉकेनस्पील।","ladder.rung.v1.4.0":"हार्प, कोटो, सितार और माउंटेन डल्सिमर।","ladder.rung.v1.5.0":"वायलिन, वायोला, चेलो और डबल बास, गज़ से और उंगलियों से छेड़कर।","ladder.rung.v1.6.0":"फ़्लूट, क्लैरिनेट, सैक्सोफ़ोन, ओबो और रिकॉर्डर।","ladder.rung.v1.7.0":"ट्रम्पेट, ट्रॉम्बोन, फ़्रेंच हॉर्न और ट्यूबा।","ladder.rung.play-along":"साथ बजाने और सीखने का मोड।","ladder.rung.v2.0.0":"बैंड: हर हिस्सा अपने वाद्य पर, हर एक का अपना वादक।","ladder.note":"जो संस्करण पूरा हो चुका है वह बना और टैग किया गया है। यह डाउनलोड नहीं है: 1.0.0 से पहले कोई डाउनलोड नहीं है।","honest.title":"आज यह कहाँ है","honest.start.title":"यह अभी बिल्कुल शुरुआत में है","honest.start.body":"संस्करण 0.14.0 DAW में लोड होता है और यथार्थ हाथों से बजते चार असली पियानो पर खुलता है, जिन्हें सामने से, ऊपर से या बगल से देखा जा सकता है, और संगीत बजते हुए कैमरा उनके बीच सरकता है। पियानो की जगह छह गिटार — स्टील-स्ट्रिंग, नायलॉन, इलेक्ट्रिक, म्यूटेड, और Handscore के अपने एम्प से बजते दो रॉक गिटार — भी मंच पर आ सकते हैं, जहाँ एक गिटारवादक के हाथ आपका चुना हुआ हिस्सा फ़्रेट करते, पिक करते और स्ट्रम करते हैं, और उसकी शीट पर TAB और कॉर्ड डायग्राम होते हैं; या तीन बेस — चार या पाँच तारों वाले दो बेस गिटार, और एक डबल बेस — जहाँ एक बेसवादक के हाथ उँगलियों से बेसलाइन बजाते हैं, स्लैप और पॉप करते हैं, और 808 की स्लाइड तार के साथ फिसलती हैं। कोई शैली, कलाकार या प्रोड्यूसर खोजें, बनाएँ दबाएँ, और चार हिस्से उसी शैली में लिखे जाते हैं, पियानो के म्यूज़िक-डेस्क पर शीट म्यूज़िक की तरह छपते हैं और हाथ उन्हें बजाते हैं — अपने DAW में MIDI या ऑडियो के रूप में खींचने, स्वर-दर-स्वर बदलने, या MIDI या PDF के रूप में निर्यात करने के लिए तैयार। हर हिस्सा एक मिक्सर में अपनी चैनल स्ट्रिप से होकर बजता है, उसे गढ़ने के लिए एक एनवेलप एडिटर है, और वह आपके अपने किसी इंस्ट्रूमेंट पर बज सकता है। गीत का दृश्य पूरे गीत सेक्शन-दर-सेक्शन बनाता है, हिट-तैयारी अंक और गीतकार के औज़ारों के साथ। सीखने के लिए बासठ सार्वजनिक-डोमेन क्लासिक हैं, रोकने, पीछे ले जाने और गाने में घूमने के लिए एक ट्रांसपोर्ट बार है, और पाठ मोड पंद्रह पाठ्यक्रम सिखाता है — लगभग ग्रेड 5 तक पियानो, स्वरलिपि पठन, लय, कर्ण प्रशिक्षण, सिद्धांत, गीत-लेखन, बोल, रैप, संयोजन, मिक्सिंग, फ़िंगर ड्रमिंग, ड्रम किट, गिटार, क्लासिकल गिटार और बेस — और आपको बजाते हुए सुनता है, MIDI पर, या सुनना चालू होने पर माइक्रोफ़ोन या केबल के ज़रिए किसी असली वाद्य या आपकी आवाज़ को। ड्रम एक ड्रम मशीन पर बजते हैं, जिसके पैडों पर आपके अपने सैंपल हैं और जिसमें एक स्टेप सीक्वेंसर है, या फिर एक ड्रम किट पर, दोनों के बीच एक ही स्विच। पियानो की जगह कोई पैड कंट्रोलर या किट भी मंच पर आ सकती है, जहाँ हाथ और ड्रमर लूप के ड्रम बजाते हैं, और आप परत-दर-परत अपने ड्रम ख़ुद बजाकर डाल सकते हैं। बाकी हर वाद्य और नए पाठ्यक्रम संस्करण-दर-संस्करण आते हैं, जैसा ऊपर की सीढ़ी दिखाती है।","honest.downloads.title":"1.0.0 से पहले कोई डाउनलोड नहीं है","honest.downloads.body":"इस पन्ने पर कोई बीटा नहीं, कोई प्रीव्यू बिल्ड नहीं और कोई शुरुआती पहुँच नहीं।","honest.network.title":"Handscore खुद कभी ऑनलाइन नहीं जाता","honest.network.body":"प्लगइन और स्टैंडअलोन ऐप में कोई नेटवर्किंग कोड नहीं है, और अगर कभी जोड़ा भी जाए तो एक बिल्ड गेट फेल हो जाता है। किसी हिस्से में आप जो अपना इंस्ट्रूमेंट लोड करते हैं, वह आपका है: वह अपनी अलग प्रोसेस में चलता है और वही करता है जो वह हमेशा करता है। किसी आगामी संस्करण में एक अपडेट-चेक जोड़ा जा सकता है, जो तब तक बंद रहेगा जब तक आप उसे चालू न करें, और जिसे एक अलग प्रोग्राम चलाएगा।","site.tagline":"असली हाथों को अपना संगीत बजाते देखें। फिर इसे अपने DAW में खींचें।","footer.licence":"स्वामित्व वाला — सर्वाधिकार सुरक्षित। © 2026 Mike Weaver, जो Havoc Software नाम से व्यापार करते हैं। ओपन सोर्स नहीं।","footer.yours":"आप जो MIDI बनाते हैं और अपने DAW में खींचते हैं, वह आपका है। Handscore के लेखक उस पर कोई स्वामित्व का दावा नहीं करते।","featuresPage.lead":"किसी भी शैली में लिखे चार हिस्से, शीट म्यूज़िक के रूप में दिखाए गए और यथार्थवादी हाथों द्वारा यथार्थवादी वाद्यों पर बजाए गए, हर हिस्सा सीधे आपके DAW में खिंचता हुआ, और संगीत के पाठ जो आपको इसे ख़ुद बजाना, लिखना और अरेंज करना सिखाते हैं।","featuresPage.version":"यह पेज बताता है कि Freally Handscore संस्करण 1.0 क्या करेगा। आज का संस्करण 0.14.0 है: 1.0 तक की राह होम पेज पर देखें।","featuresPage.numbers.parts":"हिस्से: कॉर्ड्स, धुन, काउंटरमेलोडी और बास","featuresPage.numbers.genres":"जॉनर","featuresPage.numbers.artists":"कलाकार","featuresPage.numbers.producers":"प्रोड्यूसर","featuresPage.numbers.keys":"कुंजियाँ, हर एक का नाम उसके सामने वाले हिस्से पर","featuresPage.numbers.plugins":"प्लगइन फ़ॉर्मैट, साथ में एक स्टैंडअलोन ऐप","featuresPage.numbers.languages":"भाषाएँ","featuresPage.numbers.ai":"AI मॉडल","featuresPage.free.title":"आज मुफ़्त","featuresPage.free.body":"Handscore आज मुफ़्त है: कोई पेड टियर नहीं, कोई सब्सक्रिप्शन नहीं और कोई खाता नहीं। अभी डाउनलोड करने को कुछ नहीं है, क्योंकि संस्करण 1.0.0 से पहले कोई डाउनलोड नहीं है, और बाद के संस्करण बेचे जा सकते हैं।","featuresPage.cards.title":"संस्करण 1.0 क्या करता है","featuresPage.cards.pianos.title":"चार असली पियानो","featuresPage.cards.pianos.body":"एक ग्रैंड, एक अकूस्टिक, एक अपराइट और एक होंकी-टोंक पियानो, हर एक की कुंजियाँ बजते समय हिलती हैं, और उन्हीं मापी गई पियानो आवाज़ों पर बजाया गया जिन पर Freally MIDI Master बजता है।","featuresPage.cards.strings.title":"गिटार और बास गिटार","featuresPage.cards.strings.body":"स्टील-स्ट्रिंग, नायलॉन, इलेक्ट्रिक और म्यूटेड गिटार, एक गिटारवादक के हाथों से असली फ़्रेटिंग, पिकिंग और स्ट्रमिंग के साथ, उनकी शीटों पर TAB और कॉर्ड डायग्राम, और Handscore के अपने एम्प से बजते दो रॉक गिटार; और चार या पाँच तारों वाला बेस गिटार, और डबल बेस, उंगलियों से बजाए गए, स्लैप और पॉप किए गए, 808 की स्लाइड तार के साथ फिसलती हुई।","featuresPage.cards.hands.title":"यथार्थवादी हाथ","featuresPage.cards.hands.body":"दो हाथ जो हर नोट वैसे ही बजाते हैं जैसे कोई वादक बजाता: वही उंगली जो कोई पियानोवादक चुनता, वही फ़्रेट और स्ट्रोक जो कोई गिटारवादक इस्तेमाल करता।","featuresPage.cards.sheets.title":"शीट म्यूज़िक के चार पन्ने","featuresPage.cards.sheets.body":"कॉर्ड्स, धुन, काउंटरमेलोडी और बास, हर एक अपनी अलग शीट पर, और हर नोट बजते समय रोशन होता है।","featuresPage.cards.styles.title":"हर शैली जिसे Freally MIDI Master जानता है","featuresPage.cards.styles.body":"73 जॉनर, 1,507 कलाकारों या 833 प्रोड्यूसरों में से एक चुनें, और वही नियम-आधारित जनरेटर उस शैली में चारों हिस्से लिखते हैं।","featuresPage.cards.yours.title":"आपका अपना ऑडियो और MIDI","featuresPage.cards.yours.body":"अपना ऑडियो या MIDI लाएँ, और Handscore उसे हिस्सों में पढ़ता है ताकि हाथ उन्हें बजा सकें।","featuresPage.cards.classics.title":"क्लासिक्स","featuresPage.cards.classics.body":"सीखने के लिए पब्लिक-डोमेन गीत, बच्चों के गीतों और कैरल से लेकर गानों और क्लासिकल थीम तक, हर एक दो हाथों के लिए अरेंज किया गया और मंच पर हाथों द्वारा बजाया गया। इनके सिर्फ़ कॉर्ड्स ही कभी Handscore से बाहर जा सकते हैं।","featuresPage.cards.lessons.title":"संगीत के पाठ","featuresPage.cards.lessons.body":"पहले दिन से एक पियानो कोर्स जो आपको बजाते हुए सुनता है और आपके सही बजाने पर आगे बढ़ता है, फिर शीट म्यूज़िक पढ़ने, रिदम, ईयर ट्रेनिंग, थ्योरी, सॉन्गराइटिंग और गीत के बोल, गाने के अरेंजमेंट, मिक्सिंग, फ़िंगर ड्रमिंग, ड्रम किट, गिटार, क्लासिकल गिटार और बेस के कोर्स। ज़ोर से पढ़ें स्विच चालू करें, तो हर पाठ आपको पढ़कर सुनाया जाता है और बोले जाते समय हर शब्द रोशन होता है। सुनना स्विच चालू करें, तो पाठ माइक्रोफ़ोन या केबल के ज़रिए किसी असली वाद्य या आपकी आवाज़ को सुनते हैं, केवल इसी कंप्यूटर पर।","featuresPage.cards.drums.title":"ड्रम मशीन और ड्रम किट","featuresPage.cards.drums.body":"एक ड्रम मशीन जिसके पैडों पर आपके अपने सैंपल हों, हर पैड की आवाज़ गढ़ी हुई और उसके स्टेप प्रोग्राम किए हुए, और एक पेशेवर की ड्रम किट जिसे एक ड्रमर के हाथ और पैर बजाते हैं, दोनों के बीच एक ही स्विच। यथार्थवादी हाथों द्वारा बजाया गया एक पैड कंट्रोलर, हर पैड हिट होते ही रोशन। कोई ड्रम पैटर्न जनरेट करें, अपना ख़ुद का बजाकर डालें या अपने DAW का ड्रम MIDI ले आएँ, और फ़िंगर ड्रमिंग और ड्रम किट पहली बीट से लेकर पूरे ग्रूव तक सीखें।","featuresPage.cards.songs.title":"पूरे गाने और एक मिक्सर","featuresPage.cards.songs.body":"सेक्शन-दर-सेक्शन ख़ुद एक गाना बनाएँ या किसी कलाकार के अरेंजमेंट से शुरुआत करें, फिर हर हिस्से को उसकी अपनी चैनल स्ट्रिप पर मिक्स करें, और मिक्स बनाए रखते हुए उसे बाहर खींच लें।","featuresPage.cards.drag.title":"MIDI खींचें","featuresPage.cards.drag.body":"एक बार में एक हिस्सा या चारों एक साथ, शीट्स से सीधे आपके DAW में खींचे गए, या MIDI फ़ाइल के रूप में या शीट्स की PDF के रूप में सहेजे गए।","featuresPage.cards.views.title":"सामने, ऊपर और बगल के व्यू","featuresPage.cards.views.body":"संगीत बजते समय इनके बीच बदलें; शीट्स पढ़ने लायक बने रहने के लिए घूम जाती हैं और हाथ कभी कोई नोट नहीं चूकते।","featuresPage.cards.daw.title":"किसी भी DAW में","featuresPage.cards.daw.body":"Windows, macOS और Linux पर CLAP और VST3, macOS पर AU, और बिना DAW के काम करने के लिए एक स्टैंडअलोन ऐप।","featuresPage.cards.offline.title":"ऑफ़लाइन, बिना AI","featuresPage.cards.offline.body":"कोई खाता नहीं, कोई टेलीमेट्री नहीं, कोई नेटवर्क नहीं और कोई मॉडल नहीं। हर हिस्सा, फ़िंगरिंग और हरकत नियमों से आती है।","featuresPage.compare.title":"आमने-सामने","featuresPage.compare.intro":"Freally Handscore 1.0 उन औज़ारों के बगल में, जिनसे लोग संगीत के हिस्से लिखते हैं या पियानो बजते हुए देखते हैं। दूसरे उत्पादों के सेल उनकी सार्वजनिक लिस्टिंग और समीक्षाओं से लिए गए हैं, जिन्हें अक्टूबर 2026 में जाँचा गया; जहाँ हम किसी बात की पुष्टि नहीं कर सके, वहाँ सेल यही बताता है।","featuresPage.compare.feature":"फ़ीचर","featuresPage.compare.row.generate":"नामित शैलियों में नए कॉर्ड्स, धुनें और बेसलाइन लिखता है","featuresPage.compare.legend.yes":"उपलब्ध","featuresPage.compare.legend.no":"उपलब्ध नहीं","featuresPage.compare.row.plugin":"प्लगइन के रूप में आपके DAW के अंदर चलता है","featuresPage.compare.row.hands":"नोट बजाते हुए यथार्थवादी 3D हाथ दिखाता है","featuresPage.compare.note.library":"रचनाओं की अपनी लाइब्रेरी","featuresPage.compare.legend.part":"आंशिक","featuresPage.compare.note.fingers":"उंगलियों के नंबर, हाथ नहीं","featuresPage.compare.row.sheets":"नोट्स को शीट म्यूज़िक के रूप में दिखाता है","featuresPage.compare.legend.unknown":"पुष्टि नहीं हुई","featuresPage.compare.row.drag":"MIDI को आपके DAW में खींचता है","featuresPage.compare.row.offline":"ऑफ़लाइन, बिना AI के काम करता है","featuresPage.compare.summaryTitle":"संक्षेप में","featuresPage.compare.summary":"इन चारों में से सिर्फ़ Handscore 1.0 में हर पंक्ति है: नामित शैलियों में लिखे हिस्से, उन्हें बजाते यथार्थवादी हाथ, शीट म्यूज़िक, आपके DAW में खींचना और प्लगइन।","featuresPage.compare.theyWinTitle":"वे कहाँ आगे हैं","featuresPage.compare.theyWin":"Scaler 3 कहीं ज़्यादा व्यापक म्यूज़िक-थ्योरी वर्कस्टेशन है। Synthesia आपके अपने कीबोर्ड पर रचनाएँ सीखने के लिए बना है; Handscore के पाठ संस्करण 0.6 से आपको बजाते हुए सुनते हैं, लेकिन लाइव साथ बजाने के लिए संस्करण 1.9 का इंतज़ार है। AR Pianist ऑगमेंटेड रियलिटी में अपने पियानोवादक को आपके कमरे में ले आता है, जो Handscore नहीं करता।","featuresPage.compare.fineprint":"Scaler, AR Pianist और Synthesia अपने-अपने मालिकों के ट्रेडमार्क हैं, जो Freally Handscore से संबद्ध नहीं हैं। अगर कोई सेल ग़लत हो तो हमें बताएँ, हम उसे ठीक कर देंगे।","featuresPage.why.title":"यह ऐसे क्यों बना है","featuresPage.why.rules.title":"नियम, मॉडल नहीं","featuresPage.why.rules.body":"हर हिस्सा, हर फ़िंगरिंग और हर हरकत नियमों से आती है, कहीं भी कोई मॉडल नहीं। वही शैली और वही सीड हर बार वही हिस्से देते हैं।","featuresPage.why.drag.title":"जो दिखता है, वही खिंचता है","featuresPage.why.drag.body":"शीट्स उसी MIDI से बनाई जाती हैं जिसे वे खींचती हैं, और हाथ ठीक वही नोट बजाते हैं, इसलिए आपके ट्रैक पर वही पहुँचता है जो आपने देखा।","featuresPage.why.real.title":"असली माप पर बना","featuresPage.why.real.body":"हर वाद्य अपने असली माप पर बना है: कीबोर्ड असली पियानो के आकार का है, और हर कुंजी अपने संतुलन बिंदु पर वैसे ही घूमती है जैसे असली कुंजी।","featuresPage.why.local.title":"यह आपकी मशीन पर ही रहता है","featuresPage.why.local.body":"कोई खाता नहीं, कोई टेलीमेट्री नहीं और कोई क्लाउड नहीं। प्लगइन और स्टैंडअलोन ऐप कभी ऑनलाइन नहीं जाते, और अगर कभी नेटवर्किंग कोड जोड़ा जाए तो एक बिल्ड गेट फेल हो जाता है।","featuresPage.coming.title":"अभी क्या आना बाक़ी है","featuresPage.coming.intro":"साफ़-साफ़ कहा गया, क्योंकि जो फ़ीचर सूची अपनी कमियाँ छिपाए, वह पढ़ने लायक नहीं। यह पन्ना संस्करण 1.0 के बारे में है, और Handscore एक-एक संस्करण करके बनाया जा रहा है, इसलिए इसका ज़्यादातर हिस्सा अभी बना नहीं है। 1.0 की ओर रास्ते का हर संस्करण अपनी स्थिति के साथ चिह्नित है।","featuresPage.limits.title":"1.0 क्या नहीं करता","featuresPage.limits.export":"जिस गीत की धुन किसी क्लासिक या किसी जानी-मानी धुन से मेल खाती है, वह Handscore से सिर्फ़ अपने कॉर्ड्स के रूप में बाहर जाता है।","featuresPage.limits.families":"यह पियानो, पैड कंट्रोलर और ड्रम किट, गिटार और बास गिटार बजाता है। वाद्यों का हर दूसरा परिवार 1.0 के बाद एक-एक संस्करण करके आता है, 2.0 में पूरे बैंड तक।","featuresPage.limits.learn":"इसके पाठ आपको बजाते हुए सुनते हैं, लेकिन हाथ अभी लाइव आपका अनुसरण नहीं करते: किसी भी वाद्य पर साथ बजाना संस्करण 1.9 में आता है।","featuresPage.coming.downloads":"संस्करण 1.0 से पहले कोई डाउनलोड नहीं है, और इस पन्ने पर भी कोई नहीं।","docs.intro":"Handscore हर वाद्य-परिवार पर यथार्थ हाथों की ओर बढ़ रहा है, पियानो, गिटार और बेस से लेकर फ़िंगर ड्रमिंग, गीत-लेखन और अरेंजमेंट तक के संगीत पाठों के साथ। यह मैनुअल भी संस्करण-दर-संस्करण उसके साथ बढ़ता है। अभी यह बताता है कि संस्करण 0.14.0 क्या करता है: पियानो और हाथ, पैड कंट्रोलर पर फ़िंगर ड्रमिंग, ड्रम मशीन, ड्रम किट और उसका ड्रमर, ड्रम मैप, गिटार और गिटारवादक के हाथ, बेस और बेसवादक के हाथ, तीन दृश्य, गाना बनाना, शीट म्यूज़िक, खींचना और निर्यात, एडिटर, क्लासिक, ट्रांसपोर्ट, पाठ और उनके पंद्रह पाठ्यक्रम, किसी असली वाद्य या आपकी आवाज़ को सुनना, ट्यूनर, मिक्सर, एनवेलप एडिटर, आपके अपने इंस्ट्रूमेंट, गीत का दृश्य और उसके गीत-लेखन के औज़ार, और हिट-तैयारी अंक।","docs.start.title":"शुरुआत करना","docs.agreement.title":"लाइसेंस अनुबंध","docs.stage.title":"मंच","docs.pianos.title":"पियानो","docs.play.title":"कुंजियाँ बजाना","docs.hands.title":"हाथ","docs.pads.title":"फ़िंगर ड्रमिंग","docs.machine.title":"ड्रम मशीन","docs.kit.title":"ड्रम किट","docs.drummap.title":"ड्रम मैप","docs.guitars.title":"गिटार","docs.basses.title":"बेस","docs.views.title":"दृश्य","docs.generate.title":"गाना बनाना","docs.sheets.title":"शीट म्यूज़िक","docs.tray.title":"शीट ट्रे","docs.drag.title":"अपने DAW में","docs.edit.title":"स्वरों को संपादित करना","docs.lyrics.title":"बोल","docs.seeds.title":"सीड और इतिहास","docs.classics.title":"क्लासिक्स","docs.transport.title":"ट्रांसपोर्ट","docs.lessons.title":"पाठ","docs.listen.title":"सुनना","docs.mixer.title":"मिक्सर","docs.envelopes.title":"एनवेलप एडिटर","docs.hosted.title":"आपके अपने इंस्ट्रूमेंट","docs.song.title":"गीत का दृश्य","docs.songtools.title":"गीत-लेखन के औज़ार","docs.grade.title":"हिट-तैयारी अंक","docs.shortcuts.title":"कीबोर्ड शॉर्टकट","docs.project.title":"आपका प्रोजेक्ट","docs.theme.title":"लाइट और डार्क","docs.language.title":"भाषाएँ","docs.privacy.title":"आपकी निजता","docs.start.p1":"Handscore आपके DAW के अंदर CLAP, VST3 या AU इंस्ट्रूमेंट के रूप में, या अकेले एक स्टैंडअलोन ऐप के रूप में चलता है। इसे किसी इंस्ट्रूमेंट ट्रैक पर रखें।","docs.start.p2":"संस्करण 1.0.0 से पहले कोई डाउनलोड नहीं है, और सोर्स कोड निजी है।","docs.agreement.p1":"Handscore जब पहली बार खुलता है, तो अपना लाइसेंस अनुबंध दिखाता है। जब तक आप सहमत नहीं चुनते, Handscore कुछ नहीं करता और कोई आवाज़ नहीं निकालता।","docs.agreement.p2":"आपका जवाब आपके कंप्यूटर पर रखा जाता है और Handscore की हर खुली कॉपी द्वारा साझा किया जाता है, हर DAW में और स्टैंडअलोन ऐप में भी। यदि आप अस्वीकार करते हैं, तो अनुबंध स्क्रीन पर बना रहता है, ताकि जब भी आप सहमत हों, वह तैयार रहे।","docs.stage.p1":"ऊपरी बार के नीचे मंच है: आपका चुना हुआ पियानो, उसकी 88 कुंजियाँ, A0 से C8 तक, असली पियानो के माप में, जो विंडो की पूरी चौड़ाई भरता है। हर कुंजी का नाम उसके सामने वाले हिस्से पर लिखा है — सफ़ेद कुंजियों पर गहरी स्याही में, काली कुंजियों पर सफ़ेद में — और कुंजी दबी रहने तक छिपा रहता है, ताकि आप हमेशा देख सकें कि कौन-से नोट बजाए जा रहे हैं।","docs.stage.p2":"अगर आपका कंप्यूटर 3D में नहीं बना सकता, तो मंच कुछ भी न दिखाने के बजाय यह बताता है और समझाता है कि इसे कैसे चालू करें।","docs.stage.p3":"Handscore मापता है कि आपका कंप्यूटर मंच को कितनी तेज़ी से बनाता है, और उस गुणवत्ता पर टिक जाता है जिसे वह सहजता से बनाए रख सके।","docs.pianos.p1":"चार पियानो बारी-बारी से मंच पर आते हैं, एक बार में एक: Grand Piano, Acoustic Piano, Upright Piano और Honky-Tonk Piano, हर एक का अपना आकार, फ़िनिश और आवाज़।","docs.pianos.p2":"ऊपर बाईं ओर का मोड चुनें बटन (या P) आपके विकल्प श्रेणी के अनुसार खोलता है। वाद्य में, पूर्वावलोकन पियानो बदले बिना किसी पियानो पर एक छोटी धुन बजाता है, और चुनें उसे मंच पर रख देता है, पिछले पियानो से क्रॉसफ़ेड करते हुए। आपकी पसंद आपके प्रोजेक्ट के साथ सहेजी जाती है।","docs.play.p1":"किसी कुंजी को सुनने के लिए उस पर क्लिक करें, या कुंजियों पर से सरकाते हुए उन्हें एक-एक करके बजाएँ। हर कुंजी अपने संतुलन बिंदु पर घूमते हुए नीचे जाती है, जितनी ज़ोर से बजाई जाए उतनी तेज़ी से, और नीचे रहने तक उसका नाम धुंधला रहता है और ऊपर उठने पर लौट आता है।","docs.play.p2":"आपके DAW से आने वाला MIDI पियानो बजाता है और उसकी कुंजियाँ हिलाता है। सस्टेन पेडल आपके छोड़े हुए सुरों को तब तक थामे रखता है जब तक आप उससे पैर नहीं उठा लेते।","docs.hands.p1":"दो यथार्थवादी हाथ मंच पर हर नोट वैसे ही बजाते हैं जैसे कोई पियानोवादक बजाता: हर उंगली उस अंश के लिए चुनी हुई, स्केल पर अंगूठा नीचे से निकलता हुआ, चौड़े कॉर्ड्स तक पहुँच, और जब संगीत में हाथों को एक-दूसरे के पार जाना हो तो एक हाथ उठकर दूसरे के ऊपर से जाता हुआ। जब कुछ नहीं बज रहा होता, तो वे कुंजियों पर तैयार टिके रहते हैं।","docs.hands.p2":"Handscore संगीत बजने से पहले ही तय कर लेता है कि हर नोट कौन-सा हाथ बजाएगा और किस उंगली से, ताकि कुंजियों के नीचे जाते ही हाथ वहाँ पहुँच जाएँ।","docs.pads.p1":"मोड चुनें में वाद्य के अंतर्गत पैड कंट्रोलर चुनें, या ड्रम टैब में मंच पर पैड कंट्रोलर चालू करें: सोलह पैड वाला एक कंट्रोलर मंच पर आ जाता है, और हाथ उस पर लूप के ड्रम उँगली-दर-उँगली बजाते हैं — पहले तर्जनी उँगलियाँ, हर हाथ अपनी ओर रहते हुए — जबकि बाकी हिस्से भी सुनाई देते रहते हैं। हर पैड हिट होते ही अपने किट-पीस के रंग में जगमगाता है, हिट जितना ज़ोरदार उतनी तेज़ रोशनी, और असली पैड की रोशनी की तरह धीरे-धीरे मंद होता है; गति कम करें चालू होने पर रंग बने रहते हैं और मंद होना हट जाता है। आपका प्रोजेक्ट यह चुनाव याद रखता है।","docs.pads.p2":"हर लूप के अपने ड्रम होते हैं, जो बनाएँ दबाने पर उसके साथ ही लिखे जाते हैं। बेसलाइन के बाद आने वाला ड्रम टैब उसके सोलह पैड दिखाता है: उन पर क्लिक करें, उन्हें MIDI पर किसी पैड कंट्रोलर या कीबोर्ड से बजाएँ, या कीज़ से पैड बजाएँ चालू करके उन्हें कंप्यूटर की कुंजियों से बजाएँ — 1 2 3 4, Q W E R, A S D F और Z X C V, सबसे ऊपर की पंक्ति पहले। डिफ़ॉल्ट लेआउट General MIDI के स्वर 36 से 51 को नीचे बाएँ से पैडों पर रखता है; परफ़ॉर्मेंस किक, स्नेयर और हाई-हैट को दो हाथों के लिए दर्पण की तरह उलट देता है। सीखें आपके अपने कंट्रोलर को मैप करता है: वह जैसे-जैसे माँगे, हर पैड बजाएँ, नीचे बाएँ से गिनते हुए। Esc रद्द करता है, और भूलें सामान्य डिफ़ॉल्ट पर लौटा देता है।","docs.pads.p3":"ड्रम की अपनी एक शीट होती है, मानक ड्रम नोटेशन में, हर पीस अपनी रेखा या बीच की जगह पर, हाथों के स्वरों की डंडियाँ ऊपर और पैरों की नीचे। मंच पर पैड कंट्रोलर होने पर यह डेस्क पर सबसे पहले खड़ी होती है, और उँगलियों के अंक चालू होने पर हर स्वर अपना हाथ और अपनी उँगली दिखाता है।","docs.pads.p4":"अपने ड्रम ख़ुद बजाकर डालने के लिए ड्रम टैब में रिकॉर्ड करें दबाएँ। गिनती के बाद लूप बजता है, और हर बार जब वह घूमकर लौटता है, तो आपने जो बजाया वह एक परत बन जाता है जिसके साथ वह आगे बजता है: पहले किक, फिर स्नेयर, फिर हाई-हैट। पास हटाएँ आख़िरी परत वापस ले लेता है, और रोकें टेक को रख लेता है, क्वांटाइज़ चालू हो तो सोलहवें सुरों पर बैठाकर। आपका प्रोजेक्ट हर टेक को इस जानकारी के साथ रखता है कि वह ताल के साथ कितना कसा हुआ था: कोई भी एक चुनें, या लूप के अपने ड्रम पर लौट जाएँ।","docs.pads.p5":"पाठ मोड में फ़िंगर ड्रमिंग पाठ्यक्रम इसे दिन 1 से ड्रम मशीन पर सिखाता है: अभ्यास का पैटर्न मंच के नीचे उसके स्टेप में दिखता है, अगले पैड अपनी बारी से पहले चमकते हैं और ग़लत पैड लाल चमकता है, और हर टेक बताता है कि आपने ताल से कितना आगे या पीछे बजाया। आपके हिट ड्रम मशीन के पैडों से बजते हैं, आपके अपने सैंपल भी। ऐक्सेंट और घोस्ट नोट केवल उसी टेक पर जाँचे जाते हैं जो ऐसे पैडों पर बजाया गया हो जो महसूस करते हैं कि उन पर कितनी ज़ोर से हिट हुआ, माउस या कंप्यूटर की कुंजियों से बजाए टेक पर नहीं।","docs.machine.p1":"ड्रम टैब एक ड्रम मशीन है। सबसे ऊपर स्विच चुनता है कि ड्रम कौन बजाए, और किट मेन्यू Handscore की चार इलेक्ट्रॉनिक किटों में से एक चुनता है — Sub, Floor, Neon और Wire — या शैली की अपनी किट। बाईं ओर वन-शॉट किट की आवाज़ें और आपकी अपनी आवाज़ें दिखाता है: किसी को सुनने के लिए उस पर क्लिक करें, और उसे किसी पैड पर खींचें (Alt के साथ वह एक और परत बन जाती है)। बीच में सोलह पैड हैं, दाईं ओर लूप में लूप के अपने ड्रम और आपके बजाकर डाले गए टेक रहते हैं, और मिज़ाज पूरी किट को उसका ड्राइव, स्नैप, टोन और क्रश देता है।","docs.machine.p2":"किसी पैड को चुनें, तो नीचे उसकी आवाज़ खुलती है। एक पैड में चार तक परतें होती हैं, जो वेलोसिटी के अनुसार या बारी-बारी से चुनी जाती हैं, हर एक का अपना सैंपल, गेन, पैन, ट्यून और शुरुआत। सैंपल एक वेवफ़ॉर्म की तरह दिखता है, जिसके हैंडल उसकी शुरुआत और अंत काटने और उसे फ़ेड इन और फ़ेड आउट करने के लिए हैं, और उल्टा और नॉर्मलाइज़ यह बदलते हैं कि वह कैसे बजता है, फ़ाइल को कभी नहीं। फिर पैड की ट्यून और पिच एनवेलप, उसका एम्प एनवेलप, अपने एनवेलप वाला लो-पास, हाई-पास या बैंड-पास फ़िल्टर, उसका गेन और पैन, एक चोक ग्रुप (एक हिट उसके ग्रुप के बाकी पैडों को चुप करा देता है, जैसे बंद हाई-हैट खुली हाई-हैट को काट देती है), म्यूट और सोलो। हर बदलाव तुरंत सुनाई देता है और पूर्ववत का एक कदम है; किट की आवाज़ पर रीसेट करें पैड को किट की अपनी आवाज़ लौटा देता है।","docs.machine.p3":"सैंपल जोड़ें… आपकी अपनी आवाज़ें वन-शॉट में डालता है, और फ़ाइल ब्राउज़र से खींची गई ऑडियो फ़ाइलें भी वहीं जाती हैं: WAV, AIFF या FLAC, 30 सेकंड तक लंबी। जो फ़ाइल बहुत लंबी, बहुत बड़ी, ख़ामोश या ऑडियो न हो, उसे कारण बताकर लौटा दिया जाता है। Handscore अपनी एक कॉपी रखता है, इसलिए फ़ाइल हट जाए तब भी आपका प्रोजेक्ट सैंपल बजाता है, और PDF में निर्यात किसी प्रोजेक्ट में इस्तेमाल हुए सैंपलों की सूची देता है।","docs.machine.p4":"पैड की आवाज़ के नीचे स्टेप सीक्वेंसर लूप के ड्रम को स्टेप के रूप में दिखाता है, हर पैड की एक पंक्ति और हर बार में सोलह स्टेप। कोई हिट लगाने या हटाने के लिए किसी स्टेप पर क्लिक करें, पेंट करने के लिए आर-पार खींचें, हिट हटाने के लिए राइट-ड्रैग करें और उन्हें वापस लाने के लिए वापस खींचें, और नीचे की लेन में हर हिट की वेलोसिटी तय करें। स्विंग ऑफ़-बीट के सोलहवें सुरों को देर से बजाता है, 50 से 75 % तक। कुंजियों से: ऐरो से आगे-पीछे जाएँ, Enter लगाता या हटाता है, Delete हटाता है, और Page Up और Page Down वेलोसिटी बदलते हैं। बनाएँ ने जो ड्रम लिखे और आपने जो टेक बजाकर डाले, वे स्टेप में आ जाते हैं, और हर बदलाव तुरंत सुनाई देता है, दिखता है और खींचा जा सकता है।","docs.kit.p1":"एक ही स्विच चुनता है कि आपके ड्रम कौन बजाए: ड्रम मशीन या ड्रम किट। यह ड्रम टैब में सबसे ऊपर, मिक्सर में ड्रम स्ट्रिप पर और शीट ट्रे में ड्रम के बगल में है। संगीत बजते समय स्विच करने से वह कभी नहीं रुकता: अगला हिट दूसरे पर बजता है, और अगर ड्रम मंच पर हों, तो मंच पैड कंट्रोलर से किट पर या वापस सरक जाता है। दोनों तरह से वही हिट बजते हैं, आपका प्रोजेक्ट यह चुनाव याद रखता है, और ऑडियो ड्रैग वही बजाता है जो आपने चुना।","docs.kit.p2":"ड्रम मंच पर हों और किट चुनी गई हो, तो वहाँ एक पेशेवर की किट खड़ी होती है — स्नेयर, किक, दो रैक टॉम और दो फ़्लोर टॉम, हाई-हैट, दो क्रैश, एक राइड, एक स्प्लैश, एक चाइना और एक काउबेल — ड्रमर के हाथ स्टिक थामे और पैर पैडलों पर। हर हिट वहीं पड़ता है जहाँ कोई ड्रमर मारता: दायाँ हाथ क्रॉस होकर हाई-हैट और राइड तक, रूडिमेंट और फ़िल बारी-बारी से दोनों हाथों से, किक दाएँ पैर के नीचे और हाई-हैट बाएँ के नीचे, ऐक्सेंट के लिए एड़ी ऊपर, और डबल पैडल तभी जब एक पैर साथ न दे पाए। जैज़ और बैलेड ब्रश से बजते हैं, नरम अकूस्टिक शैलियाँ रॉड से। स्टिक के नीचे ड्रम-हेड दबते हैं, और सिम्बल झूलते हैं और फिर थम जाते हैं।","docs.kit.p3":"किट की अपनी अकूस्टिक आवाज़ है, जो क्लोज़, ओवरहेड और रूम माइक्रोफ़ोन से सुनाई देती है: मिज़ाज के तीन फ़ेडर उन्हें मिलाते हैं। किट बजते समय ड्रम शीट स्टिकिंग दिखाती है — हर हाथ के स्वर पर R या L, हर पैर के स्वर पर RF या LF — क्रॉस-स्टिक और रिमशॉट अपने अलग स्वर-शीर्षों के साथ और घोस्ट नोट कोष्ठक में, और मंच पर किट होने पर यह डेस्क पर सबसे पहले खड़ी होती है। इस बीच आप पैडों की जो आवाज़ें बदलते हैं वे ड्रम मशीन की होती हैं, जो वापस स्विच करने पर सुनाई देती हैं।","docs.drummap.p1":"फ़ाइल ब्राउज़र से कोई ड्रम MIDI फ़ाइल ड्रम टैब पर खींचें, और वह लूप के ड्रम बन जाती है, हर स्वर जैसा आया था वैसा ही। उसके बगल में ड्रम मैप फ़ाइल में इस्तेमाल हुआ हर स्वर दिखाता है, उसके कितने हिट हैं और वह क्या बजाता है। इस रूप में पढ़ें वह लेआउट चुनता है जिसमें आपके DAW ने उसे लिखा था — General MIDI, Ableton Drum Rack, FL Studio FPC, Logic Drummer, EZdrummer / Superior Drummer या Addictive Drums — और हर पंक्ति को किट के किसी भी पीस पर, किट पर नहीं पर, या 808 बेसलाइन पर सेट किया जा सकता है। ड्रमर हर बदलाव तुरंत बजाता है। प्रीसेट के रूप में सेव करें आपका अपना मैप अगली फ़ाइल के लिए इसी कंप्यूटर पर रखता है, और आपका प्रोजेक्ट वह मैप रखता है जिसका वह इस्तेमाल करता है।","docs.guitars.p1":"छह गिटार मंच पर आ सकते हैं: Guitar (स्टील-स्ट्रिंग), Nylon Guitar, Electric Guitar, Muted Guitar, और दो रॉक गिटार, Overdriven Guitar और Distortion Guitar। मोड चुनें में वाद्य के अंतर्गत गिटार टैब इनकी सूची दिखाता है: पूर्वावलोकन चुनने से पहले किसी एक पर C, A माइनर, F और G स्ट्रम करता है, और चुनें उसे मंच पर रख देता है। गाना बजते समय गिटार बदलने पर भी गाना कभी नहीं रुकता।","docs.guitars.p2":"एक गिटारवादक के दोनों हाथ आपका लूप बजाते हैं, और केवल हाथ ही दिखाए जाते हैं। फ़्रेट दबाने वाला हाथ उन कॉर्ड शेप से बजाता है जो एक गिटारवादक सीखता है — ओपन कॉर्ड, E- और A-शेप के बैरे कॉर्ड, पावर कॉर्ड, ट्रायड और शेल वॉइसिंग — हर कॉर्ड पिछले कॉर्ड के पास, और हर लाइन नेक पर उस पोज़िशन में जहाँ वह सबसे सहज पड़ती है, उँगलियों के सिरे फ्रेट वायर के ठीक पीछे दबे हुए। पिकिंग वाला हाथ लय में नीचे और ऊपर स्ट्रम करता है, एक-एक स्वर पिक करता है, अंगूठे और उँगलियों से फ़िंगरस्टाइल बजाता है, या Muted Guitar के लिए अपनी हथेली तारों पर टिका देता है। किसी तेज़ लाइन पर हाथ वहीं हैमर-ऑन और पुल-ऑफ़ से स्लर करता है जहाँ कोई गिटारवादक करता, और स्लाइड उँगली को तार के साथ सरकाती है, जो फ़्रेट-दर-फ़्रेट फिसलते एक ही स्वर की तरह सुनाई देती है। हर तार जहाँ फ़्रेट किया जाता है वहाँ अपने फ़्रेट पर दबता है और जब तक उसका स्वर गूँजता है तब तक थरथराता है, ज़ोरदार स्ट्रोक पर हल्के स्ट्रोक से ज़्यादा, और म्यूट किया गया तार मुश्किल से ही।","docs.guitars.p10":"Overdriven Guitar और Distortion Guitar, Handscore के अपने एम्प से होकर बजते हैं: एक ट्यूब-शैली का प्रीएम्प, एक टोन स्टैक, एक पावर एम्प और एक स्पीकर कैबिनेट। Overdriven Guitar में क्लासिक हार्ड रॉक का क्रंच है, Distortion Guitar में मेटल का हाई गेन। एम्प से होकर पूरा कॉर्ड गड्डमड्ड हो जाता है, इसलिए दोनों कॉर्ड को पावर कॉर्ड की तरह बजाते हैं, Distortion Guitar के पावर कॉर्ड पाम-म्यूटेड, और धुन को वैसे ही बजाते हैं जैसे Electric Guitar बजाता है। ये अपने ही एक रॉक गिटार पर बजते हैं।","docs.guitars.p3":"गिटार आपके गीत का एक हिस्सा बजाता है। मोड चुनें में, “बजाता है” से आप चुनते हैं कि गिटार कॉर्ड, धुन या प्रति-धुन बजाए, और संगत से यह कि बाकी हिस्सों का क्या हो: संगत बंद होने पर, जो हिस्से गिटार नहीं बजाता वे चुप रहते हैं और उनकी शीटें धुंधली हो जाती हैं; संगत चालू होने पर, वे Grand Piano पर बजते हैं। आपका प्रोजेक्ट यह चुनाव याद रखता है।","docs.guitars.p4":"तीनों दृश्य गिटार के लिए भी काम करते हैं। सामने वादक की ओर देखता है, ऊपर नेक पर वैसे ही नीचे देखता है जैसे वादक देखता है, और बगल पिकिंग वाले हाथ और नेक को प्रोफ़ाइल में दिखाता है। म्यूज़िक स्टैंड वादक के बगल में खड़ा रहता है, और उसकी शीटें हर दृश्य की ओर घूम जाती हैं।","docs.guitars.p5":"गिटार की शीट छह-लाइन वाले TAB के ऊपर स्टाफ़ पर स्वर दिखाती है, साथ में हर बदलाव पर एक कॉर्ड डायग्राम, स्ट्रम के तीर, स्लाइड, हैमर-ऑन और पुल-ऑफ़ के स्लर, और उँगलियों के अंक चालू होने पर फ़िंगरिंग। PDF में निर्यात करें भी TAB छापता है।","docs.guitars.p6":"कॉमा कुंजी (,) या ऊपरी पट्टी में सेटिंग्स कुंजी दबाएँ, और वाद्य पेज पर Electric Guitar, रॉक गिटारों या बेस गिटारों का फ्रेट वायर चुनें, हर एक का अलग-अलग: उसकी प्रोफ़ाइल (विंटेज, पतला-ऊँचा, मीडियम-जंबो या जंबो) और उसकी धातु (निकल-सिल्वर या स्टेनलेस स्टील)। इससे नेक का रूप बदलता है, आवाज़ कभी नहीं।","docs.guitars.p7":"गिटार ख़ुद बजाने के लिए सेटिंग्स में हाथ दिखाएँ को बंद करें। हाथ छिपे होने पर, कोई स्वर छेड़ने के लिए किसी तार को किसी फ़्रेट पर दबाएँ: जब तक आप छोड़ते नहीं, स्वर बना रहता है, और उसका नाम नेक पर दिखता है। कोई MIDI कुंजी सबसे पास के तार और फ़्रेट को बजाती है।","docs.guitars.p8":"पाठ मोड में दो पाठ्यक्रम गिटार सिखाते हैं, हर एक दिन 1 से दिन 150 तक। गिटार पाठ्यक्रम, स्टील-स्ट्रिंग, इलेक्ट्रिक और म्यूटेड गिटार पर, पहले शेप और TAB सिखाता है: ओपन कॉर्ड और स्ट्रमिंग, ऑल्टरनेट पिकिंग के साथ रिफ़, पाम म्यूटिंग, पावर कॉर्ड, बैरे कॉर्ड, लेगाटो और पेंटाटोनिक स्केल, फ़िंगरपिकिंग, और ट्रेबल क्लेफ़ पढ़ना। क्लासिकल गिटार पाठ्यक्रम, Nylon Guitar पर, स्टाफ़ से पढ़ने पर चलता है, नीचे TAB के साथ: रेस्ट स्ट्रोक, बेस वाले तार और अंगूठा, मूल स्वर और शार्प, आरपेजियो, कॉर्ड, फ़्री स्ट्रोक, स्लर और एट्यूड। सुनना चालू करें, और पाठ आपका अपना गिटार सुनते हैं।","docs.guitars.p9":"गिटार के पाठ में हर आने वाला स्वर अपने तार और फ़्रेट पर एक रंगीन बिंदु की तरह दिखता है, जिसके भीतर उसकी उँगली का अंक होता है; वह बजने से पहले धीरे-धीरे उभरता है और ताल पर जगमगाता है। जब पाठ आपका इंतज़ार करता है, तो बिंदु वे स्वर दिखाते हैं जिनका वह इंतज़ार कर रहा है, और आपके बजाने से पहले वे अभ्यास का पूरा आकार दिखाते हैं। टेम्पो के बगल की “बिंदु … ms पहले” सेटिंग तय करती है कि वे कितनी जल्दी दिखें।","docs.basses.p1":"तीन बेस मंच पर आ सकते हैं: Pluck Bass और Slap Bass, दो इलेक्ट्रिक बेस गिटार, और Upright Bass, पिज़्ज़िकाटो बजाया जाने वाला एक डबल बेस। मोड चुनें में वाद्य के अंतर्गत बेस टैब इनकी सूची दिखाता है: पूर्वावलोकन चुनने से पहले किसी एक पर एक छोटी बेसलाइन बजाता है, और चुनें उसे मंच पर रख देता है। बेस आपके गीत का बेस हिस्सा बजाता है, और संगत से आप चुनते हैं कि बाकी हिस्सों का क्या हो: वे चुप और धुंधले रहें, या Grand Piano पर बजें।","docs.basses.p2":"एक बेसवादक के दोनों हाथ बेसलाइन बजाते हैं, और केवल हाथ ही दिखाए जाते हैं। नेक की नीची पोज़िशनों में फ़्रेट दबाने वाला हाथ तर्जनी, मध्यमा और कनिष्ठा से बजाता है, हर उँगली के बीच एक फ़्रेट, और ऊँची पोज़िशनों में हर फ़्रेट पर एक उँगली, और जैसे बेसवादकों को सिखाया जाता है, एक गाइड उँगली के सहारे पोज़िशन बदलता है; Upright Bass हर जगह तर्जनी, मध्यमा और कनिष्ठा ही रखता है, और उँगली का सिरा उसके बिना फ़्रेट वाले फ़िंगरबोर्ड पर तार को ठीक उसी जगह दबाता है जहाँ स्वर है। प्लकिंग वाला हाथ बारी-बारी से दो उँगलियाँ चलाता है, एक उँगली को रेक करते हुए अगले तार तक ले जाता है, घोस्ट नोट बजाता है, और Slap Bass पर नीचे के तारों को अंगूठे से स्लैप करता है और ऊँचे तारों को उँगली से पॉप करता है। Upright Bass पर वह उँगली के बगल से तार छेड़ता है।","docs.basses.p3":"बनाई गई 808 बेसलाइन की स्लाइड वैसे ही बजाई जाती हैं जैसे कोई बेसवादक बजाता: स्वर एक बार छेड़ा जाता है और उँगली तार के साथ अपने लक्ष्य तक सरकती है, जो फ़्रेट-दर-फ़्रेट फिसलती सुनाई देती है। अपने DAW में खींचे जाने या निर्यात किए जाने पर, बेस का हिस्सा हर स्लाइड को एक-दूसरे पर चढ़े स्वरों की जोड़ी के रूप में लिखता है, जिसे सैंपलर ग्लाइड की तरह बजाता है।","docs.basses.p4":"Pluck Bass और Slap Bass चार या पाँच तारों पर बजते हैं। कॉमा कुंजी (,) या ऊपरी पट्टी में सेटिंग्स कुंजी दबाएँ, और वाद्य पेज पर तार में 4 या 5 चुनें। पाँच तार एक नीचा B जोड़ते हैं, ताकि नीची 808 लाइन अपनी ही पिच पर बजे; चार तारों पर जो फ़्रेज़ नीचे के E से नीचे जाता है, वह एक सप्तक ऊपर बजाया जाता है, पूरा फ़्रेज़ एक साथ। दोनों ही सूरतों में, आप जो बेस हिस्सा खींचते या निर्यात करते हैं वह वही बेसलाइन है जो बनाई गई थी।","docs.basses.p5":"बेस की शीट चार-लाइन वाले TAB के ऊपर बेस क्लेफ़ पर स्वर दिखाती है, पाँच तारों पर पाँच लाइनें, साथ में x से चिह्नित घोस्ट नोट, स्लाइड, और स्लैप और पॉप के लिए TAB के नीचे T और P। तीनों दृश्य, म्यूज़िक स्टैंड और हाथ से बजाना वैसे ही काम करते हैं जैसे गिटारों के लिए: हाथ छिपे होने पर, कोई स्वर छेड़ने के लिए किसी तार को किसी फ़्रेट पर दबाएँ।","docs.basses.p6":"पाठ मोड में बेस पाठ्यक्रम दिन 1 से दिन 180 तक बेस सिखाता है। Pluck Bass पर वह खुले तारों और ताल पर रूट से शुरू होता है, फिर किक ड्रम के साथ कसकर जुड़े पंचम और सप्तक, नेक पर ऊपर तक के स्वर, स्केल और आरपेजियो, कंट्री और वॉल्ट्ज़ से लेकर बोसा नोवा, गॉस्पेल और ब्लूज़ तक के ग्रूव, और वॉकिंग लाइनें; दिन 151 से, Slap Bass पर स्लैप और पॉप। नेक पर बिंदु दिखाते हैं कि आपकी उँगलियाँ आगे कहाँ जाएँगी, जैसे गिटार के पाठ में, और सुनना चालू होने पर पाठ आपका अपना बेस सुनते हैं।","docs.views.p1":"मंच को सामने से, ऊपर से या बगल से देखें। मंच के ऊपरी दाएँ कोने में दृश्य का नॉब घुमाएँ, या अगले दृश्य के लिए V और पिछले के लिए Shift+V दबाएँ। संगीत बजता रहता है और कैमरा एक दृश्य से अगले पर सरकता है, और हर कुंजी, हर हाथ और हर जलता सुर ठीक ताल में रहता है। आपका प्रोजेक्ट दृश्य याद रखता है।","docs.views.p2":"सामने वादक का दृश्य है, कीबोर्ड पूरी खिड़की भरता है। ऊपर सीधे कुंजियों और हाथों पर नीचे देखता है: ग्रैंड पियानो इसके लिए अपना ढक्कन बंद करता है, और स्वरलिपियाँ ढक्कन पर अगल-बगल सपाट पड़ी रहती हैं ताकि आप उन्हें पढ़ सकें; अपराइट पर वे ऊपरी ढक्कन पर रहती हैं। बगल कुंजियों की ऊँचाई पर ऊँचे सुरों वाले सिरे से कीबोर्ड के साथ-साथ देखता है और हाथों का आकार दिखाता है — हर उँगली कैसे मुड़ती है और हर कुंजी कितनी नीचे जाती है — और डेस्क पर स्वरलिपियाँ आपकी ओर घूमी रहती हैं। बगल के दृश्य में दृश्य के नॉब के नीचे का बाईं ओर से स्विच इसकी जगह गहरे सुरों वाले सिरे से देखता है। किसी भी दृश्य में स्वरलिपि को पास से देखने के लिए उस पर क्लिक करें, या 1 से 6 दबाएँ।","docs.generate.p1":"बाईं ओर का पैनल (खिड़की के किनारे पर उसका टैब उसे दिखाता और छिपाता है) 73 शैलियों, 1,507 कलाकारों और 833 प्रोड्यूसरों में खोजता है। एक चुनें और बनाएँ या G दबाएँ: चार हिस्से — कॉर्ड, धुन, प्रति-धुन और बेसलाइन — उसी शैली में, 4 या 8 बार लंबे लिखे जाते हैं, और हाथ उन्हें पियानो पर बजाते हैं।","docs.generate.p2":"बनाएँ के पास के चिप्स मूल स्वर, स्केल (41 विकल्प), मूड, टेम्पो (20 से 999 BPM; संख्या को ऊपर या नीचे खींचें), जटिलता और 4 या 8 बार तय करते हैं, और हर चिप बताता है कि गाना किसमें बना। DAW में, DAW का अनुसरण आपके प्रोजेक्ट के टेम्पो पर लिखता है, और जब तक यह चालू है, टेम्पो चिप उसी टेम्पो पर रहता है: अपना टेम्पो रखने के लिए इसे बंद करें। स्टैंडअलोन ऐप में DAW का अनुसरण नहीं है। बजाने योग्य हिस्सों को दो हाथों के लिए सजाता है; मूल उन्हें ठीक वैसा रखता है जैसा लिखा गया।","docs.sheets.p1":"हर हिस्सा पियानो के म्यूज़िक-डेस्क पर शीट म्यूज़िक के एक पन्ने की तरह छपता है, अपने शीर्षक और पृष्ठ संख्या के साथ, और बगल में सभी हिस्सों का पूरा स्कोर खड़ा रहता है। चलते प्लेहेड के नीचे हर स्वर-शीर्ष बजते ही जगमगाता है, और लंबा हिस्सा बजते-बजते अपने पन्ने पलटता है। किसी शीट पर क्लिक करें, या 1 से 6 दबाएँ, उसे पास लाने के लिए; Esc वापस ले जाता है।","docs.tray.p1":"मंच के नीचे, ट्रे हर हिस्से को सोलो, म्यूट, लॉक और एक नए टेक के साथ रखती है। लॉक किया हुआ हिस्सा दोबारा बनाने पर बना रहता है। टेक, सपना 1–3 और फिर सपना किसी हिस्से के तीन नए संस्करण आपके मौजूदा के बगल में देते हैं: एक चुनें और रख लें।","docs.drag.p1":"किसी हिस्से को उसकी शीट से, या सब खींचें से पूरे गाने को, सीधे अपने DAW में MIDI के रूप में खींचें। निर्यात किसी हिस्से या पूरे गाने का MIDI आपकी दी हुई फ़ाइल में सहेजता है — हर स्वर की वेलोसिटी, हर हिस्से का स्तर और पैन, टेम्पो और ताल-चिह्न के साथ।","docs.drag.p2":"PDF में निर्यात शीटों को एक कवर पेज के साथ लिखता है: शीर्षक, टेम्पो, मूल स्वर और स्केल, अवधि, बार, कुल स्वर, हर हिस्से और हर पन्ने के हिसाब से, और वाद्य। क्रेडिट जोड़ें — लेखक, गायक, प्रोड्यूसर, इस्तेमाल किए गए सैंपल और उनका स्रोत, रिकॉर्ड लेबल — टाइप करते समय सुझाए गए नामों के साथ।","docs.edit.p1":"मंच, धुन, कॉर्ड, प्रति-धुन और बेसलाइन ऊपर चलते हैं। किसी हिस्से का टैब उसका अपना पियानो रोल खोलता है, एक म्यूट बिंदु, सोलो और हिस्से को खाली करने वाले × के साथ। स्वरों को चुनें, खिसकाएँ, लंबा करें, मिटाएँ, कॉपी करें, चिपकाएँ और दोहराएँ; दायाँ क्लिक करके खींचने से स्वर हटते और लौटते हैं। हर हिस्से का अपना गेन और पैन है।","docs.edit.p2":"एक या दो बार की गिनती के बाद MIDI कीबोर्ड से रोल में रिकॉर्ड करें। रोल को गाने के स्केल पर, या स्वरों वाली पंक्तियों पर समेटें: स्केल की पंक्तियाँ रंगी होती हैं और उससे बाहर का स्वर चिह्नित होता है। जैसे-जैसे आप बनाते हैं, अगला स्वर या कॉर्ड हल्का-सा सुझाया जाता है; Tab उसे रखता है, एक क्लिक एक को रखता है, और कहीं और बनाने से सुझाव हट जाते हैं।","docs.edit.p3":"ट्रांसपोर्ट के पास कॉर्ड चालू करें और एक कुंजी गाने के मूल स्वर में 3, 4 या 5 स्वरों का कॉर्ड बजाती है — माउस, कंप्यूटर कीबोर्ड या MIDI कीबोर्ड से।","docs.lyrics.p1":"धुन या प्रति-धुन के नीचे शब्द लिखें, अक्षर चिह्नित करके: वे शीट पर छपते हैं और गाए जाते समय जगमगाते हैं। हर पंक्ति के पास एक गिनती बताती है कि वह अपने बार में समाती है या नहीं। टाइप करते समय शब्द का बाकी हिस्सा सुझाया जाता है (Tab उसे ले लेता है) और ग़लत वर्तनी सुधारी जाती है, जब तक आप अपना शब्द रखने के लिए चेकमार्क न छुएँ या Shift+Tab न दबाएँ।","docs.seeds.p1":"हर रचना अपना सीड दिखाती है, और हर हिस्सा अपना टेक सीड, कॉपी के साथ। किसी गाने का सीड चिपकाएँ उसे फिर से बनाने के लिए, या किसी हिस्से का टेक सीड वह टेक वापस लाने के लिए। पीछे और आगे आपकी हर रचना से गुज़रते हैं — हर एक ठीक वैसी ही लौटती है और रीस्टार्ट के बाद भी बनी रहती है; नई रचना कभी पुरानी को नहीं दोहराती।","docs.classics.p1":"मोड चुनें के क्लासिक गीत में सीखने के लिए बासठ पब्लिक-डोमेन गीत हैं: बच्चों के गीत, क्रिसमस गीत और कैरल, लोकगीत, स्पिरिचुअल और गान, क्लासिकल थीम और पियानो के लोकप्रिय गीत। हर एक दो हाथों के लिए अरेंज किया गया है, धुन दाएँ हाथ में और कॉर्ड्स बाएँ में। शीर्षक या संगीतकार से खोजें, फिर चलाएँ चुनें।","docs.classics.p2":"क्लासिक सीखने के लिए है, ले जाने के लिए नहीं: Handscore से सिर्फ़ उसके कॉर्ड बाहर जा सकते हैं। बनाया गया कोई गाना जिसकी धुन, प्रति-धुन या बेसलाइन किसी जानी-मानी धुन से मिलती हो, उस हिस्से को ऐप में ही रखता है और कारण बताता है।","docs.transport.p1":"मंच के नीचे: पीछे करना, चलाना या रोकना, बंद करना और आगे करना, और एक टाइमलाइन जिसमें गीत का समय और हर बार पर एक निशान है। उस पल के हाथ एक छोटे पूर्वावलोकन में देखने के लिए टाइमलाइन पर पॉइंटर ले जाएँ; वहाँ जाने के लिए क्लिक करें या खींचें। तेज़ी से आगे-पीछे जाने के लिए पीछे करें या आगे करें को दबाए रखें। दोनों तरह से आप हर वह नोट सुनते हैं जिससे आप गुज़रते हैं। स्पेस चलाता और रोकता है, और टाइमलाइन पर तीर कुंजियाँ एक-एक बार आगे-पीछे करती हैं।","docs.transport.p2":"कुंजियों के पास वाला M मेट्रोनोम है। इसे चालू करें, तो हर बीट पर एक क्लिक होता है, हर बार की पहली बीट ऊँची, जबकि इसके दो बिंदु बीट दिखाते हैं।","docs.transport.p3":"जब गाने में बोल हों, तो टाइमलाइन का प्रीव्यू उस पल गाए जा रहे शब्द दिखाता है।","docs.lessons.p1":"मोड चुनें → पाठ स्टूडियो के भीतर ही पाठ मोड खोलता है: बाईं ओर पाठ्यक्रम का नक्शा और दिन के चरण, बीच में मंच और उसके नीचे पाठ का पाठ्य। नक्शे के ऊपर पाठ्यक्रम कुंजी पंद्रह पाठ्यक्रमों में से एक चुनती है: पियानो, स्वरलिपि पठन, लय, कर्ण प्रशिक्षण, प्रोड्यूसरों के लिए संगीत सिद्धांत, गीत-लेखन, बोल लेखन, रैप और फ़्लो, गीत संयोजन, मिक्सिंग, फ़िंगर ड्रमिंग, ड्रम किट, गिटार, क्लासिकल गिटार और बेस। हर पाठ्यक्रम अपने खंडों में दिन-ब-दिन चलता है, हर दिन एक निर्देशित सत्र, और हर सप्ताह दोहराने का एक दिन; पियानो पाठ्यक्रम शुरुआती (दिन 1 से 90) से प्राथमिक (91 से 400) होते हुए मध्यम (401 से 1,300) तक जाता है, फ़िंगर ड्रमिंग और ड्रम किट शुरुआती (दिन 1 से 30) से प्राथमिक (31 से 150) तक, दोनों गिटार पाठ्यक्रमों में से हर एक दिन 1 से दिन 150 तक, और बेस पाठ्यक्रम दिन 1 से दिन 180 तक। पहली बार कोई पाठ्यक्रम दिन 1 पर खुलता है; उसके बाद जारी रखें आपको सीधे उसी पाठ्यक्रम, दिन, चरण और शब्द पर ले जाता है जहाँ आप रुके थे। कोई भी दिन नक्शे से खोला जा सकता है, और पाठ से बाहर निकलें आपको उसी गीत पर लौटाता है जिसे आप छोड़कर आए थे।","docs.lessons.p2":"हर चरण पढ़ता है, दिखाता है या सुनता है। देखें: हाथ अभ्यास को उस दृश्य में बजाते हैं जो चरण बताता है, कहा जाए तो धीरे, उँगलियों के अंकों के साथ। आज़माएँ: बजाने वाली कुंजियाँ जगमगाती हैं और संगीत उनका इंतज़ार करता है। लय में: गिनती के बाद लय में, हर सुर ताल से मिलाकर जाँचा जाता है। पूरा बजाएँ: शुरू से अंत तक बजाएँ, अंत में एक सारांश के साथ। हर प्रयास ताल-खंड और ताल बताता है और सुधार का तरीक़ा देता है। लगातार कुछ सही प्रयासों के बाद चरण पूरा होता है, और दिन तब पूरा होता है जब उसका मुख्य अभ्यास पूरा बजाया जाए — और अगर उस दिन उसे लय में बजाना है, तो लय में। अभ्यास के लिए कुछ ताल-खंड लूप में चलाएँ, एक हाथ से बजाएँ जबकि मंच दूसरा बजाए, या टेम्पो बदलें; टेम्पो की सीढ़ी पर तीन साफ़ प्रयासों के बाद ताल तेज़ होती है और तीन ग़लतियों के बाद एक सीढ़ी नीचे आती है। आज़माएँ मंच की कुंजियों पर माउस से भी चलता है; लय में और पूरा बजाएँ के लिए MIDI कीबोर्ड चाहिए, या सुनना चालू होना चाहिए।","docs.lessons.p3":"ज़ोर से पढ़ें तब तक बंद रहता है जब तक आप इसे चालू न करें। तब आपके कंप्यूटर की अपनी आवाज़ पाठ पढ़ती है, हर शब्द बोले जाते समय जगमगाता है। स्पेस चलाता और रोकता है, ⏹ बंद करता है, और ⏪ या ⏩ दबाए रखने से पीछे या आगे जाते हैं; गति आधी से दुगुनी तक तय करें और इंस्टॉल की गई आवाज़ों में से एक चुनें। घड़ियाँ इस दिन और सभी दिनों में बिताया समय और आपने कितने दिन अभ्यास किया, दिखाती हैं। आपकी प्रगति इसी कंप्यूटर पर रहती है, अलग ऐप में और हर DAW में एक जैसी, और कभी किसी प्रोजेक्ट में नहीं जाती।","docs.lessons.p4":"कर्ण प्रशिक्षण एक बार में एक प्रश्न पूछता है: मंच उसे एक बार बजाता है, आप कुंजियों पर उत्तर देते हैं, और अगला प्रश्न आता है। लय के पाठ्यक्रम में मेट्रोनोम की क्लिक चरणों में हटती जाती है, हर ताल से लेकर एक भी नहीं तक, जब तक आप ख़ुद लय न साध लें। प्रोड्यूसरों के लिए संगीत सिद्धांत किसी भी बनाए गए गीत को Nashville नंबर चार्ट के रूप में दिखाता है।","docs.lessons.p5":"रचनात्मक पाठ्यक्रमों में रचने के चरण होते हैं: आप गीत के दृश्य में, उसकी बोल पट्टी या फ़्लो ग्रिड में, मिक्सर में या नोटबुक के किसी पन्ने पर काम करते हैं, और जाँचें बताता है कि उसे चरण के हर लक्ष्य के मुक़ाबले क्या मिला, गीतकार या इंजीनियर की भाषा में। जो लक्ष्य आपने जानबूझकर तोड़ा, उसे जानबूझकर चिह्नित किया जा सकता है, और तब वह पास हो जाता है। ये पाठ आपके अपने सीखने वाले गीत पर, जो आपकी प्रगति के साथ रखा जाता है, और पाठ लूपों पर काम करते हैं: पाठ मोड छोड़ते समय आपके प्रोजेक्ट का गीत और मिक्स ठीक वैसे ही रहते हैं जैसे थे।","docs.lessons.p6":"ड्रम किट पाठ्यक्रम किट को मंच पर लाता है और MIDI पर किसी इलेक्ट्रॉनिक ड्रम किट से, सुनना चालू होने पर किसी अकूस्टिक किट से, या माउस और कंप्यूटर की कुंजियों से बजाया जाता है: स्टिक की पकड़ और स्ट्रोक, सिंगल स्ट्रोक से लेकर रोल तक रूडिमेंट, पैर, बैकबीट, घोस्ट नोट, खुली हाई-हैट और राइड, शफ़ल और स्विंग, ब्रश, डबल पैडल, फ़िल और पूरे रूप, और रॉक और फ़ंक से लेकर वन-ड्रॉप, बोसा नोवा और जैज़ तक के ग्रूव, साथ में मेट्रोनोम की क्लिक जो चरणों में हटती जाती है। बाहर निकलने पर आपके प्रोजेक्ट के अपने ड्रम और वाद्य लौट आते हैं।","docs.listen.p1":"पाठ किसी असली वाद्य या आपकी आवाज़ को सुन सकते हैं। सुनना डायलॉग खोलने के लिए L या ऊपरी पट्टी में सुनना कुंजी दबाएँ: इनपुट और उसका चैनल चुनें, या सभी चैनल मिलाकर, और बजाते समय उसका लेवल हिलता देखें, साथ में क्लिपिंग के लिए एक लाइट और आपके छेड़े गए कॉर्ड का नाम। अगर कुछ नहीं आ रहा, तो डायलॉग यह बताता है, और Windows और macOS पर यह भी कि माइक्रोफ़ोन की अनुमति कहाँ दें। हेडफ़ोन मदद करते हैं: पाठ आपको सुनते हैं, स्पीकरों को नहीं।","docs.listen.p2":"DAW में, Handscore अपने ख़ुद के साइडचेन इनपुट Listen पर सुनता है, और उसके आउटपुट जैसे हैं वैसे ही रहते हैं। जब तक कोई ट्रैक उस तक न भेजा जाए, कुछ सुनाई नहीं देता: डायलॉग Ableton Live, FL Studio और Reaper में इसका तरीक़ा दिखाता है।","docs.listen.p3":"जो भी पाठ्यक्रम सुन सकता है, उसके पाठ की पट्टी पर एक सुनना स्विच होता है, जो तब तक बंद रहता है जब तक आप उसे चालू न करें। तब पियानो, स्वरलिपि पठन और सिद्धांत के पाठ्यक्रम आज़माएँ, लय में, पूरा बजाएँ और प्रश्नों में आपके सुर और कॉर्ड सुनते हैं; ड्रम किट पाठ्यक्रम किसी अकूस्टिक किट की किक, स्नेयर और हाई-हैट सुनता है और बाकी हर हिस्से का समय मापता है; लय और रैप और फ़्लो के अभ्यास क्लिक के मुक़ाबले आपकी तालियों, थपकियों या अक्षरों का समय मापते हैं; और कर्ण प्रशिक्षण आपके उत्तर गाकर लेता है, किसी भी सप्तक में। इस तरह सुना गया प्रयास सुरों और लय पर परखा जाता है, और यह बताता भी है: स्पर्श, पैडल और कोई सुर कितनी देर थामा गया, ये केवल MIDI पर परखे जाते हैं। सुनना चालू रहते हुए आपकी MIDI कुंजियाँ बजती तो रहती हैं, पर परखी नहीं जातीं।","docs.listen.p4":"रैप और फ़्लो के फ़्लो ग्रिड वाले चरणों में, रैप करें कुंजी गिनती के बाद गाना बजाती है और आप उस पर रैप करते हैं; रोकें, और आपके प्रयास का समय आपके रखे अक्षरों से मिलाया जाता है: कितने सुने गए, बीट पर आपकी पकड़, और हर अक्षर कितना पहले या देर से आया।","docs.listen.p5":"डायलॉग का ट्यूनर सुर दिखाता है और यह कि वह कितने सेंट ऊँचा या नीचा है, सुर के गूँजते रहने तक स्थिर, A4 को 415 से 466 Hz के बीच कहीं भी रखकर, और गिटार और बेस के खुले तारों के नाम के साथ। कैलिब्रेशन मापता है कि किसी आवाज़ को Handscore से निकलकर वापस आने में कितना समय लगता है, केबल से या आपके स्पीकरों से माइक्रोफ़ोन में लूप बैक करके, या क्लिक के साथ बजाकर, ताकि आप जो बजाएँ वह लय में पड़े; यह संख्या इस कंप्यूटर पर उस इनपुट के लिए रखी जाती है।","docs.listen.p6":"सब कुछ इसी कंप्यूटर पर सुना जाता है, और केवल तब जब “सुन रहा है” शब्दों वाली लाइट जली हो। न कुछ रिकॉर्ड होता है, न रखा जाता है, न भेजा जाता है: Handscore केवल आपकी सुनने की सेटिंग्स रखता है, जैसे आपका चुना इनपुट और उसकी लेटेंसी।","docs.mixer.p1":"हर हिस्से की चैनल स्ट्रिप साथ-साथ और मास्टर देखने के लिए M दबाएँ, या मिक्सर टैब। हर स्ट्रिप में एक फ़ेडर, एक पैन नॉब, तीन-बैंड EQ, रूम, इको और हीट, एक कंप्रेसर (जब तक आप चालू न करें, बंद) और ग्रैन्युलर नॉब है, साथ में एक LED मीटर और क्लिप लाइट; मास्टर का अपना फ़ेडर, ग्रैन्युलर नॉब और मीटर है। बारीक हरकत के लिए Shift के साथ फ़ेडर खींचें, या 0 dB के लिए उस पर डबल-क्लिक करें। म्यूट और सोलो कटने की बजाय धीरे से आते-जाते हैं; किसी सोलो पर Ctrl+click करके उसमें एक हिस्सा जोड़ें। हर बदलाव करते समय ही सुनाई देता है और छोड़ते ही पूर्ववत का एक कदम बन जाता है, और प्रोजेक्ट मिक्स को सहेजे रखता है।","docs.mixer.p2":"शीट के नीचे, हर हिस्से का ऑडियो ग्रिप उसे WAV के रूप में आपके DAW में खींचता है, गाने के टेम्पो पर उसकी स्ट्रिप से होकर रेंडर किया हुआ; पूरा मिक्स वैसा ही खिंचता है जैसा आप सुनते हैं और छोड़े गए हिस्सों के नाम बताता है। MIDI ड्रैग हिस्से का फ़ेडर और पैन कंट्रोलर के रूप में साथ ले जाता है और बताता है कि MIDI क्या नहीं ले जा सकता।","docs.envelopes.p1":"किसी हिस्से के टैब पर, एनवेलप बटन उस हिस्से के एनवेलप खोलता है: आवाज़, फ़िल्टर, पिच, पैन और ग्रैन्युलर, हर एक तब तक बंद जब तक आप उसे चालू न करें। कोई बिंदु खींचें, या किसी खंड को मोड़ने के लिए उसका हीरा खींचें; बिंदु जोड़ने के लिए डबल-क्लिक करें, या हटाने के लिए किसी बिंदु पर; किसी बिंदु को चुनकर उसके अंक टाइप करें, या ऐरो कुंजियों से उसे खिसकाएँ। हर एनवेलप में गहराई, समय पैमाना, वेलोसिटी और की ट्रैकिंग, थामा हुआ लूप, टेम्पो से बँधे समय, फिर से ट्रिगर, लेगाटो या हर माप पर रीसेट, और A/B मॉर्फ है। किसी आकार से शुरू करें, एनवेलप को दूसरे हिस्से में कॉपी करें, पूर्ववत करें और फिर से करें, या सब रीसेट करें; गाना बजते समय हर स्वर का एक बिंदु कर्व पर चलता है।","docs.hosted.p1":"हर हिस्सा Handscore के इंस्ट्रूमेंट की जगह आपके अपने किसी VST3 या CLAP इंस्ट्रूमेंट पर बज सकता है। हिस्से के टैब पर या मिक्सर में उसकी स्ट्रिप पर, उसका इंस्ट्रूमेंट बटन चयनकर्ता खोलता है: सबसे पहले Handscore का अपना, फिर हर वह इंस्ट्रूमेंट जो स्कैन को मानक प्लगइन फ़ोल्डरों में और आपके जोड़े फ़ोल्डरों में मिला। एक चुनें और हिस्सा उसके ज़रिए बजता है, उसकी विंडो बस एक क्लिक दूर; प्रोजेक्ट प्लगइन और उसकी आवाज़ सहेज लेता है। हर प्लगइन अपनी अलग प्रोसेस में चलता है, इसलिए जो क्रैश हो वह सिर्फ़ खुद को रोकता है, और उसकी लेटेंसी की भरपाई होती है। हाथ Handscore के इंस्ट्रूमेंट पर रहते हैं, और वह हिस्सा MIDI के रूप में खिंचता है। आपका प्रोजेक्ट जिस प्लगइन का नाम लेता है पर जो इस कंप्यूटर पर नहीं है, उसकी जगह Handscore का अपना ले लेता है, और हिस्सा यह बताता है। इस संस्करण में प्लगइन विंडो Windows पर खुलती हैं।","docs.song.p1":"स्टेज के नीचे गीत की टाइमलाइन खोलने के लिए A दबाएँ, या संयोजन टैब: बनाते समय पियानो, हाथ और शीट नज़र में रहते हैं, और टैब खुला रहने तक, या सोलो होने पर किसी भी टैब से, गीत बजता है। गीत बनाएँ किसी शैली का पूरा गीत उसके अपने रूप में देता है; उसका कोई रूप या उसका ख़ाली रूप चुनें, ख़ाली गीत शुरू करें, या बाएँ पैनल से कोई शैली टाइमलाइन पर खींच लाएँ। हर पंक्ति एक हिस्सा है, ड्रम सबसे आख़िर में, और हर सेल एक क्लिप।","docs.song.p2":"सेक्शनों को उनके हेडर और मेन्यू से जोड़ें, बीच में डालें, खिसकाएँ, नाम बदलें, लंबा और छोटा करें; क्लिप कॉपी और पेस्ट करें, साझा क्लिप को अलग बनाएँ, क्लिप को उसके कोनों से धीरे-धीरे लाएँ और ले जाएँ, तय करें कि वह कितने बार लूप करे, और उन क्लिपों को लॉक करें जिन्हें नया टेक रखेगा। किसी सेक्शन को फिर से बनाएँ, ↻ से लूप करें, या किसी क्लिप को अकेले सुनने के लिए उस पर डबल-क्लिक करें। किसी सेल को भरें: स्टेज का लूप वहाँ भेजकर, बाएँ पैनल के फ़ाइल ब्राउज़र से उस पर .mid या ऑडियो फ़ाइल डालकर, या अपने MIDI कीबोर्ड पर उसमें टेक बजाकर। क्लिप का ✎ उसके सुरों को टाइमलाइन के नीचे हिस्से के संपादक में खोलता है, जहाँ हर संपादन उस क्लिप को साझा करने वाले हर सेक्शन को बदलता है। हर बदलाव पूर्ववत का एक क़दम है।","docs.song.p3":"गीत बजते समय शीट हर सेक्शन को चिह्नित करती हैं और पन्ने पलटती हैं, और ट्रे में किसी सेक्शन पर जाएँ सबको वहाँ पलट देता है। पूरा गीत उसके सेक्शनों को मार्कर बनाकर, कोई सेक्शन उसके हेडर के ग्रिप से या कोई क्लिप उसके अपने ग्रिप से, MIDI या ऑडियो के रूप में अपने DAW में खींचें। फिर सपना पूरे गीत के तीन नए संस्करण देता है, और MIDI निर्यात करें और PDF में निर्यात करें गीत के दृश्य से भी काम करते हैं।","docs.songtools.p1":"संयोजन टैब पर, बोल पट्टी कुंजी गीत के बोलों को धुन के नीचे रखती है, हर सुर के नीचे एक अक्षर: बल वाले अक्षर चिह्नित होते हैं, पंक्तियों के अंत उनकी तुक के हिसाब से रंगे जाते हैं, हर सेक्शन पर उसकी तुक योजना लिखी होती है, और आम वाक्यांश चिह्नित होते हैं। फ़्लो ग्रिड कुंजी रैप के लिए फ़्लो ग्रिड खोलती है: हर बार के अक्षर उसके सोलहवें हिस्सों पर, तुकें रंगी हुई, हर बार के पास उसकी गिनती, और बोल ग्रिड से कितनी दूर बैठते हैं।","docs.songtools.p2":"बोलों के ऊपर गीत को एक शीर्षक दें। संस्करण गीत को एक नाम से सहेजता है और दिखाता है कि तब से क्या बदला: बोल पंक्ति-दर-पंक्ति, वे सेक्शन जो आए, गए, खिसके, जिनके नाम बदले या जिनकी लंबाई बदली, और हर हिस्से ने कौन-से सुर पाए या खोए। किसी सेक्शन का मेन्यू किसी हिस्से को वहाँ बंद करता है और फिर चालू करता है, और हर सेक्शन का हेडर उसकी ऊर्जा दिखाता है। किसी पाठ में, पोर्टफ़ोलियो कॉर्ड चिह्नों और बोलों वाली लीड शीट, बोलों की शीट और शिल्प रिपोर्ट को एक PDF में छापता है।","docs.grade.p1":"संयोजन टैब पर हिट-तैयारी कुंजी टाइमलाइन के बगल में गीत का अंक खोलती है: उसके रूप, हिस्सों और बोलों पर बारह जाँचों से एक अक्षर और 100 में से अंक, हर जाँच बताती है कि उसने क्या पाया और उसका लक्ष्य क्या है। बोलों को भी अंक देने के लिए धुन के बोल उसके बॉक्स में लिखें, बार 1 से हर बार के लिए एक पंक्ति। यह गीतकार की जाँच-सूची है जो गीत के अपने सुरों पर मापी जाती है, और PDF के कवर पर भी छपती है।","docs.shortcuts.p1":"सभी शॉर्टकट देखने के लिए ? या ऊपरी पट्टी में शॉर्टकट कुंजी दबाएँ।","docs.project.p1":"अपना DAW प्रोजेक्ट सहेजने पर गाना, उसके बदलाव, उसका मिक्स, उसके बोल, पियानो, दृश्य और क्रेडिट बने रहते हैं, और दोबारा खोलने पर सब कुछ वैसा ही लौट आता है।","docs.theme.p1":"ऊपर दाईं ओर का डार्क थीम स्विच विंडो को लाइट या डार्क करता है। Handscore आपकी पसंद याद रखता है, और आपके कंप्यूटर पर बाकी Freally ऐप्स भी।","docs.language.p1":"Handscore अठारह भाषाएँ बोलता है और आपके सिस्टम की भाषा में शुरू होता है।","docs.privacy.p1":"प्लगइन और स्टैंडअलोन ऐप कभी नेटवर्क का उपयोग नहीं करते। अगर Handscore कभी अचानक रुक जाए, तो एक छोटी रिपोर्ट आपके कंप्यूटर पर रखी जाती है और अगली बार इसके खुलने पर आपको पेश की जाती है; जब तक आप इसे रिपोर्ट करना नहीं चुनते, कुछ नहीं भेजा जाता।","docs.privacy.p2":"जब कोई पाठ सुन रहा हो, ट्यूनर दिख रहा हो या कैलिब्रेशन चल रहा हो, तो Handscore जो सुनता है उसका विश्लेषण आपके कंप्यूटर पर होता है, और वह न कभी रिकॉर्ड होता है, न रखा जाता है, न भेजा जाता है, और एक लाइट बताती है कि वह कब सुन रहा है।","kit.skip":"सामग्री पर जाएँ","kit.nav.site":"साइट","kit.nav.home":"होम","kit.nav.features":"फ़ीचर्स","kit.nav.documentation":"दस्तावेज़ीकरण","kit.nav.changelog":"बदलाव लॉग","kit.nav.language":"भाषा","kit.nav.allApps":"सभी Freally ऐप्स","kit.badge.progress":"v0.14.0 पूरा · आगे v0.15.0","kit.cta.features":"सभी फ़ीचर्स देखें","kit.cta.docs":"दस्तावेज़ीकरण पढ़ें","kit.price":"Freally Handscore आज मुफ़्त है, लेकिन हो सकता है कि यह हमेशा मुफ़्त न रहे: भविष्य के संस्करण बेचे जा सकते हैं।","kit.noDownloads":"अभी कोई डाउनलोड नहीं है, और सोर्स कोड निजी है।","kit.label.overview":"अवलोकन","kit.label.inside":"अंदर","kit.label.roadmap":"रोडमैप","kit.ladder.done":"पूरा","kit.ladder.planned":"नियोजित","kit.ladder.goal":"लक्ष्य","kit.ladder.later":"बाद में","kit.label.honesty":"ईमानदारी","kit.family.label":"Freally परिवार","kit.family.title":"<span class=\"hl-muted\">एक परिवार।</span> <span class=\"hl-bright\">दस ऐप्स।</span>","kit.cta.label":"क्या बदला","kit.cta.title":"<span class=\"hl-muted\">हर संस्करण,</span> <span class=\"hl-bright\">लिखित में।</span>","kit.cta.lede":"बदलाव लॉग में Freally Handscore में हुआ हर बदलाव, संस्करण-दर-संस्करण, सभी अठारह भाषाओं में दर्ज है।","kit.cta.changelog":"बदलाव लॉग पढ़ें","kit.footer.thisApp":"यह ऐप","kit.footer.family":"Freally परिवार","kit.status.devVersion":"विकास में · v0.14.0","kit.head.features":"<span class=\"hl-muted\">यह जो कुछ करता है,</span> <span class=\"hl-bright\">आमने-सामने।</span>","kit.label.numbers":"आँकड़ों में","kit.numbers.lead":"हर आँकड़ा ऐप से ही गिना गया है। कुछ भी अनुमानित नहीं है, और कुछ भी बढ़ाकर पूर्णांकित नहीं किया गया है।","kit.label.free":"आज मुफ़्त","kit.label.compare":"तुलना","kit.label.principles":"सिद्धांत","kit.label.limits":"सीमाएँ","kit.states.title":"स्थितियों का अर्थ","kit.states.done":"बना और टैग किया गया, पर इस साइट पर डाउनलोड नहीं","kit.states.planned":"अभी बनना बाकी है","kit.states.goal":"वह संस्करण जिस तक यह रास्ता जाता है","kit.states.later":"उसके बाद, और अभी तय नहीं","kit.states.ladder":"रास्ते का हर पड़ाव देखें","kit.head.documentation":"<span class=\"hl-muted\">यह कैसे काम करता है,</span> <span class=\"hl-bright\">क़दम-दर-क़दम।</span>","kit.search.placeholder":"दस्तावेज़ीकरण में खोजें","kit.docs.contents":"विषय-सूची","kit.head.changelog":"<span class=\"hl-muted\">हर बदलाव,</span> <span class=\"hl-bright\">संस्करण-दर-संस्करण।</span>","kit.changelog.lede":"सबसे नया पहले: Freally Handscore में जो कुछ बदला, इस साइट की हर भाषा में।","kit.changelog.versions":"संस्करण","kit.search.none":"इस साइट पर इससे कुछ भी मेल नहीं खाता।","kit.zoom.close":"बंद करें","changelog.4551c0a19ac5":"<span class=\"release__meta\"><span class=\"release__ver\">v0.14.0</span><time class=\"release__date\" datetime=\"2026-10-24\">2026-10-24</time></span>","changelog.f043ff57f36d":"बेस। मंच पर एक बेस गिटार, स्लैप बेस या डबल बेस रखें और देखें कि एक बेसवादक के हाथ आपकी बेसलाइन कैसे बजाते हैं: बारी-बारी से चलती दो उँगलियों वाला फ़िंगरस्टाइल, स्लैप वाला अंगूठा और पॉप, उँगली के बगल से छेड़ा गया डबल बेस, और तार के साथ फिसलती 808 लाइन की स्लाइड। चार या पाँच तारों पर बजाएँ। दो नए रॉक गिटार Handscore के अपने एम्प से होकर चीखते हैं। बेस पाठ्यक्रम दिन 1 से 180 में बेस सिखाता है, पहले फ़िंगरस्टाइल, फिर स्लैप।","changelog.6b02e0d363a4":"जोड़ा गया","changelog.91e7f188f73c":"<strong>तीन बेस।</strong> Pluck Bass, Slap Bass और Upright Bass, मोड चुनें में वाद्य के अंतर्गत नए बेस टैब पर। बेस, बेस हिस्सा बजाता है; संगत चुनती है कि बाकी हिस्से सुनाई देते रहें या नहीं।","changelog.96abccacb5cb":"<strong>बेसवादक के हाथ।</strong> फ़्रेट दबाने वाला हाथ ऊँची पोज़िशनों में हर फ़्रेट पर एक उँगली से और नीची पोज़िशनों में तर्जनी, मध्यमा और कनिष्ठा से बजाता है, जैसे बेसवादकों को सिखाया जाता है, और एक गाइड उँगली के सहारे पोज़िशन बदलता है; डबल बेस पर यही फ़िंगरिंग हर जगह रहती है, उँगली का सिरा फ़िंगरबोर्ड पर ठीक स्वर की अपनी जगह। प्लकिंग वाला हाथ बारी-बारी से दो उँगलियाँ चलाता है, तारों के पार रेक करता है, अंगूठे से स्लैप और उँगली से पॉप करता है, और घोस्ट नोट बजाता है। केवल हाथ ही दिखाए जाते हैं।","changelog.7c2a4843abc4":"<strong>बेस पर 808 स्लाइड।</strong> बनाई गई 808 लाइन की स्लाइड एक बार छेड़ी जाती हैं और तार के साथ फ़्रेट-दर-फ़्रेट फिसलती हैं। खींचे या निर्यात किए जाने पर, बेस का हिस्सा हर स्लाइड को एक-दूसरे पर चढ़े स्वरों की उस जोड़ी के रूप में लिखता है जिसे सैंपलर ग्लाइड की तरह सुनता है।","changelog.67ff4c86be3b":"<strong>चार या पाँच तार।</strong> सेटिंग्स, वाद्य, तार: Pluck और Slap Bass चार तारों पर या पाँच पर बजते हैं, नीचे के B के साथ। चार तारों पर, नीचे के E से नीचे जाने वाला फ़्रेज़ पूरा का पूरा एक सप्तक ऊपर चला जाता है; पाँच पर वह अपनी ही पिच पर बजता है। दोनों ही सूरतों में, आप जो हिस्सा खींचते या निर्यात करते हैं वह वही बेसलाइन है जो बनाई गई थी।","changelog.c112985081f5":"<strong>दो चीखते गिटार।</strong> Overdriven Guitar (क्रंच वाला क्लासिक हार्ड रॉक) और Distortion Guitar (हाई-गेन मेटल), गिटार टैब पर, Handscore के अपने एम्प से होकर बजते हुए: एक ट्यूब-शैली का प्रीएम्प, एक टोन स्टैक, एक पावर एम्प और एक कैबिनेट। ये पावर कॉर्ड बजाते हैं, Distortion Guitar के पाम-म्यूटेड, अपने ही एक रॉक गिटार पर।","changelog.6e87c04f93dc":"<strong>बेस शीट।</strong> बेस की शीट चार-लाइन वाले TAB (पाँच तारों पर पाँच लाइनें) के ऊपर बेस क्लेफ़ दिखाती है, साथ में घोस्ट नोट, स्लाइड, और TAB के नीचे स्लैप का T और पॉप का P।","changelog.0131eacaeaf2":"<strong>बेस पाठ्यक्रम।</strong> Pluck Bass पर दिन 1 से 180: बेस क्लेफ़ और TAB पढ़ना, दो उँगलियों की बारी-बारी चाल, रूट, पंचम और सप्तक, स्केल, आरपेजियो और ग्रूव, वॉकिंग लाइनें, और दिन 151 से Slap Bass पर स्लैप और पॉप, नेक पर बिंदुओं के साथ, और सुनना आपका अपना बेस सुनता है।","changelog.036bdc5a3264":"<strong>बेस के नेक पर बिंदु।</strong> बेस के पाठ में हर आने वाला स्वर अपने तार और फ़्रेट पर एक बिंदु की तरह दिखता है, भीतर उसकी उँगली का अंक, जैसे गिटारों पर।","changelog.2a6141e43be0":"बदला गया","changelog.9d968cf75169":"<strong>नया कर्सर।</strong> बीच में एक बिंदु वाला छल्ला तीर और इशारा करते हाथ की जगह लेता है: बिंदु वहाँ है जहाँ आप इशारा करते हैं, छल्ला उसके पीछे चलता है, दबाई जा सकने वाली हर चीज़ पर बड़ा हो जाता है और दबाते समय सिकुड़ जाता है। बाकी हर कर्सर, जैसे टेक्स्ट कर्सर और आकार बदलने वाले तीर, पहले जैसा ही रहता है।","changelog.b84be741ce89":"<strong>टॉगल हरे रंग में जलते हैं।</strong> हर टॉगल बंद होने पर स्लेटी, उस पर पॉइंटर ले जाने पर सफ़ेद, और चालू होने पर हरा होता है, चाहे पॉइंटर उस पर हो या नहीं। संयोजन के हिस्सों पर म्यूट और सोलो भी इसी नियम पर चलते हैं।","changelog.ab4c76b623e2":"<span class=\"release__meta\"><span class=\"release__ver\">v0.13.0</span><time class=\"release__date\" datetime=\"2026-10-23\">2026-10-23</time></span>","changelog.5e8ca1878684":"गिटार। मंच पर एक स्टील-स्ट्रिंग, क्लासिकल, इलेक्ट्रिक या पाम-म्यूटेड गिटार रखें और देखें कि एक गिटारवादक के हाथ आपका लूप कैसे बजाते हैं: कॉर्ड उन शेप में जो गिटारवादक इस्तेमाल करते हैं, शैली के अनुसार स्ट्रम, पिक या फ़िंगरपिक किए हुए, लाइनें नेक पर वहाँ फ़्रेट की हुई जहाँ वे सबसे सहज पड़ती हैं, और हैमर-ऑन, पुल-ऑफ़ और स्लाइड वहीं जहाँ कोई असली वादक उनका इस्तेमाल करता। तार फ़्रेट पर दबते हैं और गूँजते समय थरथराते हैं, और शीटें कॉर्ड डायग्राम के साथ TAB दिखाती हैं। चुनें कि गिटार कौन-सा हिस्सा बजाए और बाकी हिस्से सुनाई देते रहें या नहीं। दो गिटार पाठ्यक्रम, आधुनिक और क्लासिकल, गिटार सिखाते हैं, दोनों दिन 1 से 150 तक, और नेक पर बिंदु दिखाते हैं कि आपकी उँगलियाँ आगे कहाँ जाएँगी।","changelog.cfeacd97871b":"<strong>चार गिटार।</strong> Guitar (स्टील-स्ट्रिंग), Nylon Guitar, Electric Guitar और Muted Guitar, मोड चुनें में वाद्य के अंतर्गत नए गिटार टैब पर। पूर्वावलोकन चुनने से पहले हर एक पर C, A माइनर, F और G स्ट्रम करता है। गाना बजते समय गिटार बदलने पर भी गाना कभी नहीं रुकता।","changelog.704616c6d4b1":"<strong>गिटारवादक के हाथ।</strong> फ़्रेट दबाने वाला हाथ उन कॉर्ड शेप से बजाता है जो एक गिटारवादक सीखता है — ओपन कॉर्ड, E- और A-शेप के बैरे कॉर्ड, पावर कॉर्ड, ट्रायड और शेल वॉइसिंग — हर कॉर्ड पिछले कॉर्ड के पास, और हर लाइन उस पोज़िशन में जहाँ वह सबसे सहज पड़ती है, उँगलियों के सिरे फ्रेट वायर के ठीक पीछे दबे हुए। पिकिंग वाला हाथ लय में नीचे और ऊपर स्ट्रम करता है, एक-एक स्वर पिक करता है, अंगूठे और उँगलियों से फ़िंगरस्टाइल बजाता है, या म्यूटेड गिटार के लिए हथेली तारों पर टिका देता है। केवल हाथ ही दिखाए जाते हैं।","changelog.efb9bd040b56":"<strong>हैमर-ऑन, पुल-ऑफ़ और स्लाइड।</strong> किसी तेज़ लाइन पर हाथ वहीं स्लर करता है जहाँ कोई गिटारवादक करता, और स्लाइड उँगली को तार के साथ हर फ़्रेट के पार सरकाती है, जो फ़्रेट-दर-फ़्रेट फिसलते एक ही स्वर की तरह सुनाई देती है।","changelog.643312ac2899":"<strong>तार जो प्रतिक्रिया देते हैं।</strong> हर तार जहाँ फ़्रेट किया जाता है वहाँ अपने फ़्रेट पर दबता है और जब तक उसका स्वर गूँजता है तब तक थरथराता है, ज़ोरदार स्ट्रोक पर हल्के स्ट्रोक से ज़्यादा, म्यूट किया गया तार मुश्किल से ही, चाहे हाथ दिखें या छिपे हों।","changelog.9d87c80cfb58":"<strong>गिटार क्या बजाता है, और संगत।</strong> चुनें कि गिटार कॉर्ड, धुन या प्रति-धुन बजाए। संगत बंद होने पर, जो हिस्से वह नहीं बजाता वे चुप रहते हैं और उनकी शीटें धुंधली हो जाती हैं; संगत चालू होने पर, वे Grand Piano पर बजते हैं। आपका प्रोजेक्ट यह चुनाव याद रखता है।","changelog.294f2493925b":"<strong>TAB और कॉर्ड डायग्राम।</strong> गिटार की शीट छह-लाइन वाले TAB के ऊपर स्टाफ़ पर स्वर दिखाती है, हर बदलाव पर कॉर्ड डायग्राम, स्ट्रम के तीर, स्लाइड और हैमर-ऑन और पुल-ऑफ़ के स्लर, और उँगलियों के अंक चालू होने पर फ़िंगरिंग। PDF में निर्यात करें में भी TAB है।","changelog.1f1d5ca2284e":"<strong>गिटार के तीन दृश्य।</strong> सामने वादक की ओर देखता है, ऊपर नेक पर वैसे ही नीचे देखता है जैसे वादक देखता है, और बगल पिकिंग वाले हाथ और नेक को प्रोफ़ाइल में दिखाता है। म्यूज़िक स्टैंड वादक के बगल में खड़ा रहता है, और उसकी शीटें हर दृश्य की ओर घूम जाती हैं।","changelog.abdfa644b4d6":"<strong>फ्रेट वायर।</strong> सेटिंग्स में एक नया वाद्य पेज है: इलेक्ट्रिक गिटार का फ्रेट वायर चुनें — विंटेज, पतला-ऊँचा, मीडियम-जंबो या जंबो, निकल-सिल्वर या स्टेनलेस स्टील में। इससे नेक का रूप बदलता है, आवाज़ कभी नहीं।","changelog.cdbed4e3256a":"<strong>गिटार ख़ुद बजाएँ।</strong> हाथ छिपे होने पर, किसी तार को किसी फ़्रेट पर दबाकर वह स्वर छेड़ें, जो आपके छोड़ने तक बना रहता है और जिसका नाम नेक पर दिखता है। कोई MIDI कुंजी सबसे पास के तार और फ़्रेट को बजाती है।","changelog.6babc793bfef":"<strong>गिटार पाठ्यक्रम।</strong> गिटार (स्टील-स्ट्रिंग, इलेक्ट्रिक और म्यूटेड गिटार पर) पहले शेप और TAB सिखाता है: ओपन कॉर्ड और स्ट्रमिंग, ऑल्टरनेट पिकिंग के साथ रिफ़, पाम म्यूटिंग, पावर कॉर्ड, बैरे कॉर्ड, लेगाटो और पेंटाटोनिक स्केल, फ़िंगरपिकिंग, और ट्रेबल क्लेफ़ पढ़ना। क्लासिकल गिटार (नायलॉन गिटार पर) स्टाफ़ से पढ़ने पर चलता है, नीचे TAB के साथ: रेस्ट स्ट्रोक, बेस वाले तार और अंगूठा, मूल स्वर और शार्प, आरपेजियो, कॉर्ड, फ़्री स्ट्रोक, स्लर और एट्यूड। दोनों में दिन 1 से 150, और सुनना आपका अपना गिटार सुनता है।","changelog.9466a05a46ac":"<strong>नेक पर बिंदु।</strong> गिटार के पाठ में हर आने वाला स्वर अपने तार और फ़्रेट पर एक रंगीन बिंदु की तरह दिखता है, भीतर उसकी उँगली का अंक, बजने से पहले धीरे-धीरे उभरता हुआ और ताल पर जगमगाता हुआ; प्रतीक्षा मोड वे स्वर दिखाता है जिनकी वह प्रतीक्षा करता है, और आपके बजाने से पहले अभ्यास का पूरा आकार। बिंदु कितनी जल्दी दिखें, यह टेम्पो के बगल में तय करें।","changelog.e39749a272fe":"<strong>ऊपरी पट्टी की कुंजियाँ।</strong> सुनना, शॉर्टकट और नई सेटिंग्स कुंजी (,) अब आइकन हैं, और हर एक पर पॉइंटर ले जाने पर उसका नाम दिखता है, ताकि ऊपरी पट्टी अपनी चौड़ाई में समा जाए।","changelog.83ccac5ded77":"<span class=\"release__meta\"><span class=\"release__ver\">v0.12.0</span><time class=\"release__date\" datetime=\"2026-10-19\">2026-10-19</time></span>","changelog.9cc20e44893e":"लाइव लिसनिंग। पाठ अब असली वाद्य और असली आवाज़ सुनते हैं: किसी पाठ्यक्रम के लिए सुनना चालू करें, और पियानो पाठ्यक्रम माइक्रोफ़ोन से आपका अकूस्टिक पियानो सुनता है, ड्रम किट पाठ्यक्रम आपकी अकूस्टिक किट की किक, स्नेयर और हाई-हैट, रैप और फ़्लो बीट पर आपके अक्षर, और कर्ण प्रशिक्षण आपके गाए उत्तर — सब सुरों और लय पर परखे जाते हैं, जैसे MIDI कुंजियों पर। सुनना डायलॉग में एक ट्यूनर और एक लेटेंसी कैलिब्रेशन है। सब कुछ आपके कंप्यूटर पर सुना जाता है, केवल तब जब लाइट जली हो, और न कुछ रिकॉर्ड होता है, न रखा जाता है, न भेजा जाता है।","changelog.bf779e7e1025":"<strong>सुनना डायलॉग।</strong> L या ऊपरी पट्टी में सुनना कुंजी दबाएँ: इनपुट और उसका चैनल चुनें (या सभी चैनल, मिलाकर), उसका लेवल और क्लिप लाइट देखें, आपके छेड़े गए कॉर्ड का नाम देखें, और कुछ न आ रहा हो तो तुरंत जानें, साथ में यह भी कि Windows और macOS पर माइक्रोफ़ोन की अनुमति कहाँ दें। DAW में, Handscore अपने ख़ुद के साइडचेन इनपुट Listen पर सुनता है, उसके मुख्य आउटपुट बिना बदले, और डायलॉग दिखाता है कि Ableton Live, FL Studio और Reaper में उस तक कोई ट्रैक कैसे भेजें।","changelog.8f4dc2184742":"<strong>लाइट।</strong> <em>सुन रहा है</em> शब्दों वाली एक लाइट ऊपरी पट्टी, पाठ की पट्टी और फ़्लो ग्रिड में ठीक तब तक दिखती है जब तक इनपुट खुला है, और केवल तभी। इनपुट केवल तब खुलता है जब कोई पाठ सुन रहा हो, ट्यूनर दिख रहा हो या कैलिब्रेशन चल रहा हो, और पाठ छोड़ने, विंडो बंद करने या रोकने के कुछ ही सेकंड में बंद हो जाता है।","changelog.a25a986acc4c":"<strong>आपको सुनने वाले पाठ।</strong> जो भी पाठ्यक्रम सुन सकता है उसमें एक सुनना स्विच है, जो तब तक बंद रहता है जब तक आप उसे चालू न करें। पियानो, स्वरलिपि पठन और सिद्धांत के पाठ्यक्रम किसी अकूस्टिक पियानो या किसी भी दूसरे वाद्य के सुर और कॉर्ड सुनते हैं, आज़माएँ, लय में, पूरा बजाएँ और प्रश्नों में, MIDI जैसी ही जाँचों और फ़ीडबैक के साथ, <em>कान से परखा गया</em> के निशान के साथ: सुर और लय, कभी भी स्पर्श, पैडल या यह नहीं कि कोई सुर कितनी देर थामा गया। कोई कॉर्ड अपने सुरों के नामों से गिना जाता है, और मंच जो बजाता है उसे आपका बजाया नहीं समझा जाता।","changelog.5c5bfa0fb63d":"<strong>माइक्रोफ़ोन से ड्रम किट।</strong> ड्रम किट पाठ्यक्रम किसी अकूस्टिक किट की किक, स्नेयर और हाई-हैट सुनता है, हाई-हैट के साथ बजी किक को दोनों के रूप में, और बाकी हर हिस्से को उसके समय पर परखता है।","changelog.10606f858c8b":"<strong>आवाज़ से रैप और फ़्लो और लय।</strong> लय और रैप और फ़्लो के अभ्यास क्लिक के मुक़ाबले आपके अक्षरों, तालियों या थपकियों का समय मापते हैं, और फ़्लो ग्रिड का <em>रैप करें</em> रैप किए गए प्रयास का समय आपके रखे अक्षरों से मिलाता है, पहले या देर से, ताकि आप बीट पर अपनी पकड़ सुन सकें। कुछ भी पहचाना नहीं जाता: न कोई शब्द, न कोई आवाज़।","changelog.a77396ec8a04":"<strong>गाकर कर्ण प्रशिक्षण।</strong> अपना उत्तर गाएँ: वह किसी भी सप्तक में गिना जाता है, इसलिए नीची आवाज़ उसे एक सप्तक नीचे गा सकती है।","changelog.9b71e7aedb2c":"<strong>ट्यूनर।</strong> सुर और यह कि वह कितने सेंट ऊँचा या नीचा है, सुर के गूँजते रहने तक स्थिर, A4 को 415 से 466 Hz तक रखकर, और गिटार और बेस के खुले तारों के नाम के साथ।","changelog.48248965431c":"<strong>लेटेंसी कैलिब्रेशन।</strong> कैलिब्रेशन मापता है कि किसी आवाज़ को Handscore से निकलकर वापस आने में कितना समय लगता है, केबल से या आपके स्पीकरों से माइक्रोफ़ोन में लूप बैक करके, या क्लिक के साथ बजाकर, और यह संख्या इस कंप्यूटर पर उस इनपुट के लिए रख लेता है, ताकि आप जो बजाएँ वह लय में पड़े।","changelog.6e1e7067accb":"<span class=\"release__meta\"><span class=\"release__ver\">v0.11.0</span><time class=\"release__date\" datetime=\"2026-10-19\">2026-10-19</time></span>","changelog.1208381835ec":"ड्रम मशीन और ड्रम किट। ड्रम टैब अब एक असली ड्रम मशीन है: उसके पैडों पर अपने ख़ुद के सैंपल रखें, उनकी परतें बनाएँ, हर पैड की आवाज़ गढ़ें, और अपनी बीट स्टेप-दर-स्टेप प्रोग्राम करें। या ड्रम को एक पूरी अकूस्टिक किट पर स्विच करें और देखें कि एक ड्रमर के हाथ और पैर आपकी बीट कैसे बजाते हैं, हर स्ट्रोक वहीं जहाँ कोई असली ड्रमर बजाता। संगीत बजते हुए एक ही स्विच दोनों के बीच ले जाता है, दोनों में वही हिट। इम्पोर्ट किया गया ड्रम MIDI एक ड्रम मैप से पढ़ा जाता है जिसे आप पंक्ति-दर-पंक्ति सेट कर सकते हैं, और ड्रम किट पाठ्यक्रम दिन 1 से 150 में आपके पहले स्ट्रोक से लेकर पूरे गानों तक किट सिखाता है।","changelog.7c23af602295":"<strong>ड्रम मशीन।</strong> सोलह पैड, हर एक में वेलोसिटी के अनुसार या बारी-बारी से चार तक परतें, और उसकी अपनी ट्यून, पिच एनवेलप, एम्प एनवेलप, अपने एनवेलप वाला फ़िल्टर, गेन, पैन, चोक ग्रुप, म्यूट और सोलो। फ़ाइल बदले बिना किसी सैंपल को काटें, फ़ेड करें, उल्टा करें, नॉर्मलाइज़ करें और उसका गेन बदलें। हर बदलाव पूर्ववत का एक कदम है और तुरंत सुनाई देता है।","changelog.89b709b63ac0":"<strong>Handscore की अपनी ड्रम किटें।</strong> चार इलेक्ट्रॉनिक किटें — Sub, Floor, Neon और Wire — हर एक में वह हर आवाज़ जो ड्रम इस्तेमाल करते हैं, तीन वेलोसिटी परतों और दो राउंड रॉबिन में, और किसी शैली के ड्रम उस किट पर शुरू होते हैं जो उसके अनुकूल हो। ड्राइव, स्नैप, टोन और क्रश किट को उसका मिज़ाज देते हैं।","changelog.257fba39181e":"<strong>पैडों पर आपके अपने सैंपल।</strong> फ़ाइल ब्राउज़र से कोई WAV, AIFF या FLAC किसी पैड पर छोड़ें, या <em>सैंपल जोड़ें…</em> से कोई जोड़ें। जो फ़ाइल बहुत लंबी, बहुत बड़ी, ख़ामोश या ऑडियो न हो, उसे कारण बताकर लौटा दिया जाता है। Handscore अपनी एक कॉपी रखता है, इसलिए मूल फ़ाइल हट जाए तब भी प्रोजेक्ट बजता है, और आपके सैंपल PDF में निर्यात में सूचीबद्ध होते हैं।","changelog.6b00189bd87e":"<strong>स्टेप सीक्वेंसर।</strong> लूप के 4 या 8 बार के लिए हर पैड की स्टेप-पंक्ति: किसी स्टेप पर क्लिक करें, आर-पार पेंट करें, मिटाने के लिए राइट-ड्रैग करें और वापस लाने के लिए वापस खींचें, हर हिट की वेलोसिटी तय करें, और ऑफ़-बीट को स्विंग दें। बनाएँ ने जो पैटर्न लिखा और आपने जो टेक बजाकर डाले, वे इसमें आ जाते हैं, और हर बदलाव तुरंत सुनाई देता है, दिखता है और खींचा जा सकता है।","changelog.354397d3cc08":"<strong>ड्रम किट।</strong> मंच पर एक पेशेवर की किट — स्नेयर, किक, दो रैक टॉम और दो फ़्लोर टॉम, हाई-हैट, दो क्रैश, राइड, स्प्लैश, चाइना और काउबेल — ड्रमर के हाथ स्टिक थामे और पैर पैडलों पर। हर हिट वहीं पड़ता है जहाँ कोई ड्रमर मारता: दायाँ हाथ क्रॉस होकर हाई-हैट तक, रूडिमेंट और फ़िल बारी-बारी से दोनों हाथों से, किक और हाई-हैट पैरों के नीचे, और डबल पैडल तभी जब एक पैर साथ न दे पाए। जैज़ और बैलेड के लिए ब्रश, नरम अकूस्टिक शैलियों के लिए रॉड। इसकी अपनी अकूस्टिक आवाज़, क्लोज़, ओवरहेड और रूम माइक्रोफ़ोन के साथ जिन्हें आप मिक्स कर सकते हैं।","changelog.f0b2a589c2a6":"<strong>ड्रम मशीन या ड्रम किट।</strong> ड्रम टैब में, ड्रम स्ट्रिप पर और ट्रे में ड्रम के बगल में एक ही स्विच चुनता है कि आपके ड्रम कौन बजाए। गाना बजते समय स्विच करने से वह कभी नहीं रुकता: अगला हिट दूसरे पर बजता है, और मंच उसी पर चला जाता है। आपका प्रोजेक्ट यह चुनाव याद रखता है, और ऑडियो ड्रैग वही बजाते हैं जो आपने चुना।","changelog.ae274e274c50":"<strong>ड्रम मैप।</strong> आपके DAW से आया ड्रम MIDI हर पंक्ति को वैसा ही रखता है जैसी वह आई थी। अपने DAW का लेआउट चुनें (General MIDI, Ableton Drum Rack, FL Studio FPC, Logic Drummer, EZdrummer / Superior Drummer, Addictive Drums) या हर पंक्ति को किसी किट-पीस पर, <em>किट पर नहीं</em> पर, या 808 बेसलाइन पर सेट करें, और ड्रमर उसे तुरंत बजाता है। अपने ख़ुद के मैप सेव करें।","changelog.5929431e1824":"<strong>ड्रम किट पाठ्यक्रम।</strong> पाठ मोड में MIDI पर इलेक्ट्रॉनिक ड्रम किट के साथ दिन 1 से 150: स्टिक की पकड़ और स्ट्रोक, सिंगल और डबल स्ट्रोक, पैराडिडल, फ़्लैम, ड्रैग और रोल, पैर, बैकबीट, घोस्ट नोट, खुली हाई-हैट और राइड, शफ़ल और स्विंग, ब्रश और रॉड, डबल पैडल, फ़िल और रूप, और रॉक और फ़ंक से लेकर वन-ड्रॉप, बोसा नोवा और जैज़ तक के ग्रूव, साथ में मेट्रोनोम की क्लिक जो चरणों में हटती जाती है।","changelog.92e2bf5a0b9c":"<strong>ड्रम मशीन पर फ़िंगर ड्रमिंग।</strong> फ़िंगर ड्रमिंग पाठ्यक्रम अब ड्रम मशीन के पैडों से बजता है, और अभ्यास का पैटर्न मंच के बगल में दिखता है।","changelog.df6470b1e841":"<span class=\"release__meta\"><span class=\"release__ver\">v0.10.0</span><time class=\"release__date\" datetime=\"2026-10-17\">2026-10-17</time></span>","changelog.6d2456347b5e":"फ़िंगर ड्रमिंग। एक पैड कंट्रोलर मंच पर आता है, जिसके सोलह पैड हर हिट पर जगमगाते हैं, और यथार्थ हाथ उस पर आपके लूप के ड्रम उँगली-दर-उँगली बजाते हैं। अब हर लूप के अपने ड्रम होते हैं, जो एक ड्रम शीट पर छपते हैं। किसी भी पैड कंट्रोलर पर अपने ड्रम ख़ुद बजाकर डालें, लूप के हर चक्कर के साथ परत-दर-परत, और जो टेक पसंद आएँ उन्हें रखें। फ़िंगर ड्रमिंग पाठ्यक्रम इसे पहली बीट से लेकर पूरे ग्रूव तक सिखाता है।","changelog.9f50ff1513e0":"<strong>मंच पर पैड कंट्रोलर।</strong> इसे मोड चुनें में वाद्य के अंतर्गत चुनें, या ड्रम टैब में चालू करें: एक 4×4 पैड कंट्रोलर, जिसके पैडों पर हाथ लूप के ड्रम बजाते हैं, पहले तर्जनी उँगलियाँ, हर हाथ अपनी ओर रहते हुए। बाकी हिस्से भी सुनाई देते रहते हैं। आपका प्रोजेक्ट यह चुनाव याद रखता है।","changelog.e64037f005b8":"<strong>हर पैड हिट होते ही जगमगाता है।</strong> हर किट-पीस का अपना रंग है, और हिट की ताक़त तय करती है कि मंद होने से पहले वह कितना तेज़ चमके, असली पैड की रोशनी की तरह। गति कम करें चालू होने पर रंग बने रहते हैं और मंद होना हट जाता है।","changelog.766fe929f61e":"<strong>हर लूप पर ड्रम।</strong> बनाएँ अब MIDI Master के ड्रम जनरेटरों से लूप के ड्रम भी लिखता है। 808 बेसलाइन के साथ किक और 808 एक ही पैटर्न के रूप में आते हैं, और बेसलाइन का नया टेक अपने साथ नए ड्रम भी लाता है।","changelog.18971f931e55":"<strong>ड्रम टैब।</strong> स्क्रीन पर सोलह पैड, बेसलाइन टैब के बाद, अपने बिंदु और अपने × के साथ। उन पर क्लिक करें, उन्हें किसी MIDI कंट्रोलर से बजाएँ, या कीज़ से पैड बजाएँ चालू करके उन्हें कंप्यूटर की कुंजियों से बजाएँ (1 2 3 4, Q W E R, A S D F, Z X C V)। डिफ़ॉल्ट लेआउट (नीचे बाएँ पैड से General MIDI के स्वर 36 से 51) या दर्पण की तरह उलटा परफ़ॉर्मेंस लेआउट चुनें। सीखें आपके अपने कंट्रोलर को मैप करता है: जब जो पैड माँगा जाए, उसे बजाएँ।","changelog.d30547a5121a":"<strong>ड्रम शीट।</strong> ड्रम हिस्सा मानक ड्रम नोटेशन में छपता है, हर पीस अपनी रेखा या बीच की जगह पर, हाथों के स्वरों की डंडियाँ ऊपर और पैरों की नीचे। यह बाकी शीटों के साथ डेस्क पर खड़ी होती है (मंच पर पैड कंट्रोलर होने पर सबसे पहले) और उनकी तरह इसकी भी अपनी नंबर कुंजी है, और यह सोलो और म्यूट के साथ ट्रे में और PDF में भी है। उँगलियों के अंक चालू होने पर हर स्वर अपना हाथ और अपनी उँगली दिखाता है।","changelog.5fcbc2452dda":"<strong>अपने ड्रम ख़ुद बजाकर डालें।</strong> गिनती के बाद लूप के ऊपर रिकॉर्ड करें: हर बार जब लूप घूमकर लौटता है, आपका बजाया पास एक परत बन जाता है जिसके साथ वह आगे बजता है, ताकि आप पहले किक, फिर स्नेयर, फिर हाई-हैट जोड़ सकें। पास हटाएँ आख़िरी परत वापस ले लेता है, और रोकें टेक को रख लेता है, क्वांटाइज़ चालू हो तो सोलहवें सुरों पर बैठाकर। आपका प्रोजेक्ट हर टेक को इस जानकारी के साथ रखता है कि वह कितना कसा हुआ था; कोई भी एक चुनें, या लूप के अपने ड्रम पर लौट जाएँ।","changelog.d5b28d4df7b8":"<strong>फ़िंगर ड्रमिंग पाठ्यक्रम।</strong> पाठ मोड में दिन 1 से 150: तर्जनी उँगलियाँ, फिर अंगूठे और बीच की उँगलियाँ, बैकबीट, किक की जगहें, स्विंग, ऐक्सेंट और घोस्ट नोट, फ़िल, शैलियों के ग्रूव, एक पैड पर और कई पैडों के आर-पार रूडिमेंट, ट्रिपलेट और शफ़ल, लीनियर ग्रूव, साथ में मेट्रोनोम की क्लिक जो चरणों में हटती जाती है। अगले पैड अपनी बारी से पहले चमकते हैं, ग़लत पैड लाल चमकता है, और हर टेक बताता है कि आप ताल से कितना आगे या पीछे थे। माउस या कंप्यूटर की कुंजियों से बजाए गए टेक के ऐक्सेंट नहीं जाँचे जाते।","changelog.bb31c9fcf9cb":"<strong>DAW का अनुसरण केवल DAW में।</strong> स्टैंडअलोन ऐप में DAW का अनुसरण स्विच नहीं है। DAW में, DAW का अनुसरण चालू रहते टेम्पो चिप DAW के टेम्पो पर रहता है; अपना टेम्पो रखने के लिए इसे बंद करें।","changelog.e77d5ee11f6c":"<strong>संयोजन लेबल की कुंजियाँ।</strong> पूर्ववत करें, फिर से करें, म्यूट, सोलो और ज़ूम के − और + संयोजन लेबल की पंक्ति पर छोटे आइकन हैं; यह पंक्ति नीचे की कुंजियाँ स्क्रॉल होने पर भी नज़र में रहती है। म्यूट और सोलो चालू रहते जगमगाते हैं, और पॉइंटर के नीचे हर कुंजी का अपना रंग होता है।","changelog.50f8bc668b74":"<span class=\"release__meta\"><span class=\"release__ver\">v0.9.0</span><time class=\"release__date\" datetime=\"2026-10-17\">2026-10-17</time></span>","changelog.48baf93edf6a":"पियानो से आगे के पाठ। पाठ मोड में पियानो पाठ्यक्रम के साथ नौ नए पाठ्यक्रम आ गए हैं: असली शीट म्यूज़िक पढ़ना, लय, कर्ण प्रशिक्षण, Nashville Number System के साथ प्रोड्यूसरों के लिए संगीत सिद्धांत, गीत-लेखन, रैप और फ़्लो की एक अलग राह के साथ बोल लेखन, गीत संयोजन और मिक्सिंग, हर एक पहले पाठ से अपने प्राथमिक खंड के अंत तक दिन-ब-दिन। पियानो पाठ्यक्रम ख़ुद अब लगभग ग्रेड 5 तक चलता है। रचनात्मक पाठ्यक्रम गीत के दृश्य में, बोल पट्टी पर और मिक्सर में किए जाते हैं, और शिल्प के ऐसे नियमों से जाँचे जाते हैं जिन्हें आप ख़ारिज कर सकते हैं; गीत के दृश्य को वे गीतकार के औज़ार मिलते हैं जिनका ये पाठ्यक्रम उपयोग करते हैं।","changelog.d6ab249214f0":"<strong>पाठ मोड में दस पाठ्यक्रम।</strong> नक्शे के ऊपर पाठ्यक्रम चुनने की जगह: पियानो, स्वरलिपि पठन, लय, कर्ण प्रशिक्षण, प्रोड्यूसरों के लिए संगीत सिद्धांत, गीत-लेखन, बोल लेखन, रैप और फ़्लो, गीत संयोजन और मिक्सिंग, हर एक के अपने पास किए गए दिन, अपनी जगह और अपनी घड़ियाँ; जारी रखें वही पाठ्यक्रम खोलता है जिसमें आप थे। पाठ मोड आपके प्रोजेक्ट को कभी नहीं बदलता: पाठ जो कुछ हिलाता है, वह आपके निकलते ही वापस रख दिया जाता है, और पाठ के बीच आपका DAW जो प्रोजेक्ट सहेजता है, वह वैसा ही सहेजा जाता है जैसा वह था।","changelog.3d47fd1323dd":"<strong>लगभग ग्रेड 5 तक पियानो पाठ्यक्रम।</strong> दिन 401 से 1,300: हर मेजर और माइनर कुंजी अपनी सही उँगली-व्यवस्था के साथ, तिहाई और छठे के अंतर पर स्केल, सप्तम कॉर्ड के आरपेजियो, सोलहवें सुर, दो-भाग वाली रचनाएँ, सोनाटीना, रोमांटिक, जैज़ और युगल रचनाएँ जिनमें मंच साथ बजाता है, याद से बजाना, और लगभग ग्रेड 3, 4 और 5 पर पड़ाव-जाँच।","changelog.7c030855b3fc":"<strong>स्वरलिपि पठन।</strong> देखने से पहले सुनें, स्टाफ़ के पहचान-चिह्न, क़दम और छलांगें, कुंजी-चिह्न, लेजर लाइनें और कॉर्ड, और हर दिन आपके स्तर पर नई साइट-रीडिंग, शीट संगीत की अपनी कुंजी में छपी हुई।","changelog.101d58d454d2":"<strong>लय।</strong> गिनती, सोलहवें और ट्रिपलेट तक ताल का विभाजन, सिंकोपेशन, स्विंग, कंपाउंड और विषम मीटर, और एक या दो कुंजियों पर पॉलीरिद्म, साथ में मेट्रोनोम की एक क्लिक जो चरणों में हटती जाती है जब तक आप ख़ुद लय न साध लें।","changelog.9773ae1570b4":"<strong>कर्ण प्रशिक्षण।</strong> मंच एक प्रश्न बजाता है और आप कुंजियों पर उत्तर देते हैं, एक बार में एक प्रश्न: ऊँचा या नीचा, अंतराल, मेजर या माइनर, कॉर्ड और उनके इनवर्ज़न, बेस लाइनों के रूप में कैडेंस और प्रोग्रेशन, और धुनें व लय जिन्हें आप सुनकर दोबारा बजाते हैं।","changelog.5fe00efe6b26":"<strong>प्रोड्यूसरों के लिए संगीत सिद्धांत।</strong> स्केल डिग्री, अंतराल, कॉर्ड और उनके काम, प्रोग्रेशन, मोड, और Nashville Number System — कोई भी बनाया गया गीत नंबर चार्ट के रूप में, बँटे हुए बारों और पहले धकेले गए कॉर्डों के साथ।","changelog.bc8ada8b4e41":"<strong>गीत-लेखन, बोल लेखन, रैप और फ़्लो, और गीत संयोजन।</strong> आपके पहले गीत से एक दर्जन गीतों तक दिन-ब-दिन, कई शैलियों में, गीत के दृश्य, नोटबुक और बोल पट्टी में: हर चरण का जाँचें बताता है कि उसे क्या मिला और कहाँ, और जो भी लक्ष्य आपने जानबूझकर तोड़ा, उसे जानबूझकर चिह्नित किया जा सकता है।","changelog.71310f87543d":"<strong>मिक्सिंग।</strong> गेन स्टेजिंग, संतुलन, पैनिंग, EQ, कंप्रेशन, रूम और इको, और लाउडनेस, मिक्सर में पाठ लूपों पर; जाँचें लूप को प्रिंट करता है और उसके शिखर, उसकी लाउडनेस और उसका वास्तविक शिखर मापता है। आपके प्रोजेक्ट का अपना मिक्स किसी पाठ से कभी नहीं बदलता।","changelog.9373aa367a64":"<strong>गीत के दृश्य में गीत-लेखन के औज़ार।</strong> गीत का शीर्षक; धुन के नीचे बोल पट्टी, हर अक्षर अपने सुर के नीचे और उसका बल चिह्नित, पंक्तियों के अंत तुक के हिसाब से रंगे हुए और हर सेक्शन पर उसकी तुक योजना; आम वाक्यांश चिह्नित; किसी एक सेक्शन में कोई हिस्सा बंद और फिर चालू; हर सेक्शन की ऊर्जा; गीत के नाम वाले संस्करण और तब से क्या बदला; रैप के लिए फ़्लो ग्रिड; और एक पोर्टफ़ोलियो PDF — कॉर्ड चिह्नों और बोलों वाली लीड शीट, बोलों की शीट और शिल्प रिपोर्ट।","changelog.b82b445328ca":"<span class=\"release__meta\"><span class=\"release__ver\">v0.8.0</span><time class=\"release__date\" datetime=\"2026-10-16\">2026-10-16</time></span>","changelog.578b5d28a79c":"गीत का दृश्य। Handscore अब सिर्फ़ लूप नहीं, पूरे गीत लिखता, बनाता और बजाता है: किसी भी शैली के अपने रूप में एक पूरा गीत बनाएँ, या संयोजन टैब की टाइमलाइन पर सेक्शन-दर-सेक्शन उसे गढ़ें, और हाथ व शीट उसे पहले बार से आख़िरी बार तक बजाते हैं, साथ-साथ पन्ने पलटते हुए। गीत के ड्रम अपनी अलग स्ट्रिप पर होते हैं, गीत पूरा, सेक्शन-दर-सेक्शन या क्लिप-दर-क्लिप आपके DAW में खिंचता है, और उसके साथ एक हिट-तैयारी अंक आता है जो एक-एक जाँच में दिखाता है कि वह गीत-लेखन के व्यावहारिक नियमों पर कैसा उतरता है।","changelog.b62ffaa12ca0":"<strong>संयोजन टैब।</strong> A दबाएँ: गीत की टाइमलाइन स्टेज के नीचे जुड़ जाती है, ताकि बनाते समय पियानो, हाथ और शीट नज़र में रहें, और टैब खुला रहने तक (या किसी भी टैब से सोलो करने पर) गीत बजता है। किसी शैली का पूरा गीत बनाएँ, उसका कोई रूप या उसका ख़ाली रूप चुनें, ख़ाली गीत शुरू करें, या बाएँ पैनल से कोई शैली टाइमलाइन पर खींच लाएँ।","changelog.3711bc940735":"<strong>हाथ से गीत बनाएँ।</strong> सेक्शन जोड़ें, बीच में डालें, खिसकाएँ, नाम बदलें, लंबा और छोटा करें; क्लिप कॉपी और पेस्ट करें, साझा क्लिप को अलग बनाएँ, क्लिप को धीरे-धीरे लाएँ और ले जाएँ, तय करें कि वह कितने बार लूप करे, और उन क्लिपों को लॉक करें जिन्हें नया टेक रखेगा। किसी सेक्शन को फिर से बनाएँ, किसी एक को लूप करें, या किसी क्लिप को अकेले सुनने के लिए उस पर डबल-क्लिक करें। हर बदलाव पूर्ववत का एक क़दम है।","changelog.3a48bd4ed77a":"<strong>सेल को अपने ढंग से भरें।</strong> स्टेज का लूप किसी सेक्शन में भेजें, नए फ़ाइल ब्राउज़र से किसी सेल पर <code>.mid</code> या ऑडियो फ़ाइल डालें (ऑडियो सुरों में बदल जाता है), या अपने MIDI कीबोर्ड पर किसी सेल में टेक बजाएँ, चाहें तो क्वांटाइज़ के साथ।","changelog.bcf7416c3978":"<strong>गीत में ही क्लिप के सुर संपादित करें।</strong> क्लिप का ✎ उसके सुरों को टाइमलाइन के नीचे हिस्से के संपादक में खोलता है: उस क्लिप को साझा करने वाले हर सेक्शन में सुर चुनें, खिसकाएँ, लंबे करें, बनाएँ, कॉपी, पेस्ट और हटाएँ, या केवल एक बदलने के लिए उसे अलग बनाएँ। अपने चुने बार से MIDI कीबोर्ड पर सुर बजाकर डालें।","changelog.bda265df4980":"<strong>पूरे गीत में शीट और हाथ।</strong> हर शीट हर सेक्शन को दोहरी बार-रेखा के बाद चिह्नित करती है और किसी हिस्से के विराम को उसकी गिनती के साथ एक बार में दिखाती है; पन्ने का बीच पार होते ही उसका ऊपरी आधा अगले पन्ने पर पलट जाता है, और <em>किसी सेक्शन पर जाएँ</em> हर शीट को वहाँ पलट देता है। हाथ सेक्शनों के आर-पार अपनी चालें तय करते हैं, और जिस हाथ के पास बजाने को कुछ नहीं, वह कुंजियों से उठकर आराम करता है।","changelog.6a41964e3d04":"<strong>ड्रम की पंक्ति।</strong> गीत के ड्रम शैली की ड्रम मशीन पर, मिक्सर में अपनी अलग स्ट्रिप पर बजते हैं। बजाने-योग्य स्वर-विन्यास में वे केवल वही रखते हैं जो दो हाथ और दो पैर बजा सकें; कच्चा हर चोट रखता है।","changelog.909f3c615e53":"<strong>गीत आपके DAW में।</strong> पूरा गीत उसके सेक्शनों को मार्कर बनाकर, कोई एक सेक्शन या कोई एक क्लिप, MIDI या ऑडियो के रूप में खींचें (15 मिनट तक)। MIDI निर्यात और PDF में निर्यात गीत के दृश्य से भी काम करते हैं।","changelog.e1e1d7a49efa":"<strong>पूरे गीत का फिर सपना।</strong> गीत के तीन नए संस्करण उसके अपने रूप, सुर, टेम्पो और ताल में, आपके लॉक किए क्लिप बचे रहते हैं; जो पसंद आए, उसे रखें।","changelog.9d5296c87435":"<strong>हिट-तैयारी अंक।</strong> गीत के रूप, हिस्सों और बोलों पर बारह जाँचों से एक अक्षर और 100 में से अंक: हुक कितनी बार लौटता है और कितनी जल्दी आता है, इंट्रो की लंबाई, सेक्शनों के बीच अंतर, शैली के लिए टेम्पो, धुन का विस्तार और उसकी रेखा, और बोल कैसे बैठते हैं, तुक मिलाते हैं और दोहराते हैं। हर जाँच बताती है कि उसने क्या पाया और उसका लक्ष्य क्या है, इसलिए अंक सिखाता है; बोलों को भी अंक देने के लिए धुन के बोल उसके बॉक्स में लिखें। यह PDF के कवर पर भी है।","changelog.9960bf9700bd":"<span class=\"release__meta\"><span class=\"release__ver\">v0.7.0</span><time class=\"release__date\" datetime=\"2026-10-16\">2026-10-16</time></span>","changelog.89f5c24a8af1":"मिक्सर। अब हर हिस्सा अपनी चैनल स्ट्रिप से होकर एक मास्टर में बजता है — फ़ेडर, पैन, EQ, रूम, इको, हीट, एक कंप्रेसर और एक ग्रैन्युलर नॉब — मीटर, म्यूट और सोलो के साथ, और यह सब आपके प्रोजेक्ट के साथ सहेजा जाता है। किसी भी हिस्से को, या पूरे मिक्स को, ठीक वैसा ही जैसा आप सुनते हैं, ऑडियो के रूप में अपने DAW में खींचें। एनवेलप एडिटर से हर हिस्से की आवाज़ गढ़ें, और किसी भी हिस्से को अपने किसी VST3 या CLAP इंस्ट्रूमेंट पर बजाएँ।","changelog.8b1d7b62602b":"<strong>मिक्सर।</strong> M दबाएँ: हर हिस्से की स्ट्रिप साथ-साथ और मास्टर — छपे पैमाने वाला फ़ेडर जो आपके पॉइंटर के साथ चलता है, अपनी क्लिप लाइट वाला LED मीटर, नॉब की ग्रिड (लो, मिड, हाई, रूम, इको, हीट), गेन-रिडक्शन लाइट वाला कंप्रेसर, पैन, सोलो और म्यूट। हर हरकत चलते-चलते सुनाई देती है और छोड़ते ही पूर्ववत का एक कदम बन जाती है।","changelog.2869671be357":"<strong>धीरे से आते-जाते म्यूट और सोलो।</strong> कोई हिस्सा कटने की बजाय 30 ms में धीमा होकर बंद होता है और फिर लौटता है, और सोलो सिर्फ़ सोलो किए गए हिस्से सुनाता है — Ctrl+click से एक और जुड़ता है।","changelog.fcb6690799bd":"<strong>ग्रैन्युलर नॉब।</strong> हर स्ट्रिप और मास्टर पर: 0 % पर कुछ नहीं से लेकर 100 % पर कणों, गूँजों और ध्वनि की धुंध के बादल तक — एक ऐसी आवाज़ जो किसी भी हिस्से को एम्बिएंट बना देती है। इसका सीड प्रोजेक्ट से आता है, इसलिए हर रेंडर एक जैसा निकलता है।","changelog.57a83d56df21":"<strong>ऑडियो के रूप में खींचना।</strong> हर हिस्से का ऑडियो ग्रिप उस हिस्से को 24-bit WAV के रूप में खींचता है, गाने के टेम्पो पर उसकी स्ट्रिप से होकर रेंडर किया हुआ; पूरा मिक्स वैसा ही खिंचता है जैसा आप सुनते हैं और छोड़े गए हिस्सों के नाम बताता है।","changelog.b2176c506737":"<strong>मिक्स साथ ले जाने वाले MIDI ड्रैग।</strong> किसी हिस्से का फ़ेडर और पैन फ़ाइल में CC 7 और CC 10 के रूप में जाते हैं, और ग्रिप बताता है कि MIDI क्या नहीं ले जा सकता।","changelog.5b174d5cb7c6":"<strong>एनवेलप एडिटर।</strong> हर जनरेटर के आवाज़, फ़िल्टर, पिच, पैन और ग्रैन्युलर एनवेलप, हर एक तब तक बंद जब तक आप उसे चालू न करें: खींचने के लिए बिंदु, मोड़ने के लिए खंड, थामा हुआ लूप, टेम्पो से बँधे समय, वेलोसिटी और की ट्रैकिंग, फिर से ट्रिगर या लेगाटो, A/B मॉर्फ, शुरुआती आकार, दूसरे हिस्से में कॉपी, पूर्ववत और फिर से करना, और कर्व पर चलता हर स्वर का एक लाइव बिंदु।","changelog.747aa74c96df":"<strong>आपके अपने इंस्ट्रूमेंट।</strong> हर हिस्सा Handscore के इंस्ट्रूमेंट की जगह आपके अपने किसी VST3 या CLAP इंस्ट्रूमेंट पर बज सकता है: हिस्से के टैब या स्ट्रिप पर, स्कैन में मिले इंस्ट्रूमेंट में से उसे चुनें, वहीं से उसकी विंडो खोलें, और आपका प्रोजेक्ट प्लगइन और उसकी आवाज़ सहेज लेता है। हर प्लगइन अपनी अलग प्रोसेस में चलता है, इसलिए जो क्रैश हो वह सिर्फ़ खुद को रोकता है, और उसकी लेटेंसी की भरपाई होती है। हाथ Handscore के इंस्ट्रूमेंट पर रहते हैं, और वह हिस्सा MIDI के रूप में खिंचता है।","changelog.ddebf2581fd7":"<span class=\"release__meta\"><span class=\"release__ver\">v0.6.0</span><time class=\"release__date\" datetime=\"2026-10-16\">2026-10-16</time></span>","changelog.1d54e0107a4f":"पाठ। अब Handscore पियानो सिखाता है, दिन-ब-दिन, आपके बिल्कुल पहले सुरों से लेकर लगभग ग्रेड 2 के स्तर तक: दो खंडों में 400 दिन, शुरुआती और प्राथमिक, हर दिन अपना एक निर्देशित सत्र। हाथ हर अभ्यास किसी भी दृश्य से करके दिखाते हैं, फिर पाठ्यक्रम आपको अपने MIDI कीबोर्ड पर बजाते हुए सुनता है और तभी आगे बढ़ता है जब सब सही हो। ज़ोर से पढ़ें चालू करें और आपके कंप्यूटर की अपनी आवाज़ आपको पाठ पढ़कर सुनाती है, हर शब्द बोले जाते समय जगमगाता है।","changelog.7cf885e0b28b":"<strong>स्टूडियो में ही पाठ।</strong> मोड चुनें → पाठ पियानो पाठ्यक्रम खोलता है: बाईं ओर पाठ्यक्रम का नक्शा और दिन के चरण, बीच में मंच, उसके नीचे पाठ का पाठ्य। पाठ से बाहर निकलें आपको उसी गीत पर लौटा देता है जिसे आप छोड़कर आए थे।","changelog.1c23de3f48f7":"<strong>पियानो के 400 दिन।</strong> शुरुआती (दिन 1–90) और प्राथमिक (दिन 91–400): बैठने का ढंग और हाथ का आकार, पाँच-उँगली की स्थितियाँ, ग्रैंड स्टाफ़ पढ़ना, लय, कॉर्ड, पेडल, स्केल और आरपेजियो, दोनों हाथ साथ और बजाने के लिए रचनाएँ, हर सप्ताह दोहराने का एक दिन और पहले का काम जो समय आने पर लौटता है।","changelog.1a00ed521da6":"<strong>सुनना और जाँचना, तीन तरीक़ों से।</strong> <em>आज़माएँ</em>: बजाने वाली कुंजियाँ जगमगाती हैं और संगीत उनका इंतज़ार करता है। <em>लय में</em>: गिनती के बाद लय में, हर सुर ताल से मिलाकर जाँचा जाता है। <em>पूरा बजाएँ</em>: शुरू से अंत तक बजाएँ, अंत में एक सारांश के साथ।","changelog.93f77c21d390":"<strong>शिक्षक जैसी प्रतिक्रिया।</strong> हर प्रयास ताल-खंड और ताल बताता है और सुधार का तरीक़ा देता है — छूटा हुआ सुर, जल्दी या देर से, जुड़ा या अलग, पेडल — और बताता है कि क्या अच्छा रहा।","changelog.03b65d4d96a6":"<strong>अभ्यास के औज़ार।</strong> कुछ ताल-खंडों को लूप में चलाएँ, एक हाथ से बजाएँ जबकि मंच दूसरा हाथ बजाए, टेम्पो की सीढ़ी चढ़ें (तीन साफ़ प्रयासों के बाद एक सीढ़ी ऊपर, तीन ग़लतियों के बाद एक नीचे) और किसी भी दृश्य में उँगलियों के अंकों के साथ धीमे प्रदर्शन देखें। जैसे-जैसे आप कुंजियों के नाम सीखते हैं, वे धुँधले होते जाते हैं।","changelog.deb6f2d0e7f9":"<strong>ज़ोर से पढ़ें।</strong> जब तक आप इसे चालू न करें, बंद रहता है, और याद रखा जाता है। आपके कंप्यूटर की आवाज़ पाठ पढ़ती है, बोला जा रहा शब्द कराओके स्क्रीन की तरह जगमगाता है और पाठ्य उसे दिखाए रखने के लिए सरकता है। स्पेस से चलाएँ और रोकें, बंद करें, पीछे या आगे जाने के लिए ⏪ या ⏩ दबाए रखें, गति आधी से दुगुनी तक तय करें और आवाज़ चुनें; एक घड़ी बीता और बचा हुआ पढ़ने का समय दिखाती है।","changelog.b9d693ff0bb1":"<strong>आपकी प्रगति, सहेजी हुई।</strong> जो दिन आप पार कर चुके, हर पाठ में और सब में मिलाकर बिताया समय, और जिन दिनों आपने अभ्यास किया, दिनों, घंटों, मिनटों और सेकंडों में — इसी कंप्यूटर पर, अलग ऐप में और हर DAW में। जारी रखें ठीक वहीं खोलता है जहाँ आप रुके थे: दिन, चरण और शब्द।","changelog.2f7168838eb6":"<span class=\"release__meta\"><span class=\"release__ver\">v0.5.0</span><time class=\"release__date\" datetime=\"2026-10-15\">2026-10-15</time></span>","changelog.cb681d22c8c6":"ऊपर से और बगल से दृश्य। हाथों को सामने से, ठीक ऊपर से या बगल से देखें, और संगीत बजते हुए एक दृश्य से दूसरे पर सरकें — कुंजियाँ, हाथ और जलते हुए सुर एक भी ताल नहीं चूकते। ऊपर से देखने पर ग्रैंड पियानो अपना ढक्कन बंद कर लेता है और स्वरलिपियाँ उस पर सपाट पड़ी रहती हैं, पढ़ने के लिए तैयार; बगल से हाथों का आकार दिखता है: हर उँगली कैसे मुड़ती है और हर कुंजी कितनी नीचे जाती है।","changelog.92ffe6279372":"<strong>तीन दृश्य: सामने, ऊपर और बगल।</strong> मंच के ऊपरी दाएँ कोने में दृश्य का नॉब घुमाएँ, या अगले दृश्य के लिए V और पिछले के लिए Shift+V दबाएँ। आपका प्रोजेक्ट दृश्य याद रखता है।","changelog.51b3e3c98cbc":"<strong>बिना रुकावट का बदलाव।</strong> कैमरा पियानो के आर-पार कभी गए बिना एक दृश्य से अगले पर सरकता है, और हलचल के दौरान संगीत बजता रहता है: हर कुंजी, हर हाथ और हर जलता सुर ठीक वहीं होता है जहाँ कैमरा स्थिर रहने पर होता।","changelog.24e5e2980ffb":"<strong>ऊपर: कुंजियाँ और हाथ ऊपर से।</strong> ग्रैंड पियानो अपनी टेक मोड़ता है, म्यूज़िक डेस्क को सपाट लिटाता है और ढक्कन बंद करता है; स्वरलिपियाँ डेस्क से उठती हैं, कुंजियों के ऊपर रुकती हैं और बंद ढक्कन पर अगल-बगल लेट जाती हैं, आपकी जगह से सीधी पढ़ी जा सकें इस तरह। अपराइट पियानो पर स्वरलिपियाँ ऊपरी ढक्कन पर लेटती हैं।","changelog.ea29eaefbaec":"<strong>बगल: हाथों की प्रोफ़ाइल।</strong> कैमरा कुंजियों की ऊँचाई पर ऊँचे सुरों वाले सिरे से कीबोर्ड के साथ-साथ देखता है — या दृश्य के नॉब के नीचे <em>बाईं ओर से</em> चुनकर, गहरे सुरों वाले सिरे से — और स्वरलिपियाँ डेस्क पर उसकी ओर घूम जाती हैं ताकि पढ़ी जा सकें।","changelog.49ab9c89770a":"<strong>हर ओर से हाथ।</strong> वे जिन कुंजियों को बजाते हैं उन पर अपनी छाया डालते हैं, और ऊपर से कोई उँगली का सिरा कभी किसी कुंजी या पियानो के ढाँचे में नहीं धँसता।","changelog.31bd22333d53":"<strong>हर दृश्य में स्वरलिपि पास से।</strong> उस पर क्लिक करें, या 1 से 5 दबाएँ; Esc दृश्य पर लौटाता है।","changelog.7acb71645827":"<strong>हर दृश्य में सुचारु।</strong> दृश्य या पियानो के हर बदलाव के बाद Handscore फिर से जाँचता है कि मंच कितना सुचारु चल रहा है, और अगर वह धीमा हो गया हो तो गुणवत्ता घटाता है और आपको बताता है।","changelog.d524626e7e53":"<span class=\"release__meta\"><span class=\"release__ver\">v0.4.0</span><time class=\"release__date\" datetime=\"2026-10-15\">2026-10-15</time></span>","changelog.1afdc18898f2":"बनाएँ, पढ़ें और खींचें। 73 शैलियों, 1,507 कलाकारों या 833 प्रोड्यूसरों में से खोजें, बनाएँ दबाएँ, और चार हिस्से — कॉर्ड, धुन, प्रति-धुन और बेसलाइन — उसी शैली में लिखे जाते हैं और हाथ उन्हें पियानो पर बजाते हैं। हर हिस्सा पियानो के म्यूज़िक-डेस्क पर असली शीट म्यूज़िक की तरह छपता है, पूरे स्कोर के साथ, और हर स्वर बजते ही जगमगाता है। किसी हिस्से को, या पूरे गाने को, सीधे अपने DAW में खींचें, किसी भी स्वर को उसके अपने पियानो रोल में बदलें, और MIDI या शीटों का PDF अपने क्रेडिट्स के साथ निर्यात करें।","changelog.e5fa15165f43":"<strong>किसी भी शैली में बनाएँ।</strong> बाईं ओर के पैनल में कोई शैली, कलाकार या प्रोड्यूसर खोजें (ऐप के किनारे पर उसका टैब उसे दिखाता और छिपाता है) और बनाएँ या G दबाएँ। पास के चिप्स स्केल का मूल स्वर, स्केल (41 विकल्प), मूड, टेम्पो (20 से 999 BPM; संख्या को ऊपर या नीचे खींचें), जटिलता और 4 या 8 बार तय करते हैं, और हर चिप बताता है कि गाना किसमें बना। <em>DAW का अनुसरण</em> आपके प्रोजेक्ट के टेम्पो पर लिखता है।","changelog.9b105b8264c8":"<strong>चार हिस्से, हाथों से बजते हुए।</strong> कॉर्ड, धुन, प्रति-धुन और बेसलाइन — दो हाथों के लिए सजाए हुए (<em>बजाने योग्य</em>) या ठीक जैसे लिखे गए (<em>मूल</em>)। हर रचना अपने 4 या 8 बार भरती है, और 4 से 8 पर जाने पर पहले चार दोहराए जाते हैं।","changelog.99862da9695f":"<strong>असली शीट म्यूज़िक।</strong> हर हिस्सा म्यूज़िक-डेस्क पर एक पन्ने की तरह छपता है, अपने शीर्षक और पृष्ठ संख्या के साथ, और बगल में सभी हिस्सों का पूरा स्कोर। चलते प्लेहेड के नीचे हर स्वर-शीर्ष बजते ही जगमगाता है, और लंबा हिस्सा बजते-बजते अपने पन्ने पलटता है। किसी शीट पर क्लिक करें, या 1 से 5 दबाएँ, उसे पास लाने के लिए; Esc वापस ले जाता है।","changelog.4ed6b96e134b":"<strong>शीट ट्रे।</strong> मंच के नीचे, हर हिस्सा सोलो, म्यूट, लॉक और एक नए टेक के साथ। लॉक किया हुआ हिस्सा दोबारा बनाने पर बना रहता है।","changelog.2b9c198c01ea":"<strong>अपने DAW में खींचें।</strong> एक हिस्से को, या <em>सब खींचें</em> से पूरे गाने को, उसकी शीट से अपने DAW में MIDI के रूप में खींचें।","changelog.471d0e4ba86d":"<strong>निर्यात।</strong> किसी हिस्से या पूरे गाने का MIDI सहेजें — हर स्वर की वेलोसिटी, हर हिस्से का स्तर और पैन, टेम्पो और ताल-चिह्न के साथ।","changelog.142257343a9f":"<strong>PDF में निर्यात।</strong> शीटों का PDF, एक कवर पेज के साथ: शीर्षक, टेम्पो, मूल स्वर और स्केल, अवधि, बार, कुल स्वर, हर हिस्से और हर पन्ने के हिसाब से, और वाद्य। क्रेडिट जोड़ें — लेखक, गायक, प्रोड्यूसर, इस्तेमाल किए गए सैंपल और उनका स्रोत, रिकॉर्ड लेबल — टाइप करते समय सुझाए गए नामों के साथ।","changelog.1531fe3dfe30":"<strong>हर हिस्से के लिए एक टैब।</strong> ऊपर मंच, धुन, कॉर्ड, प्रति-धुन और बेसलाइन; हर हिस्से का टैब अपने पियानो रोल, एक म्यूट बिंदु, सोलो और उसे खाली करने वाले × के साथ।","changelog.dc61e3f5b735":"<strong>स्वरों को संपादित करें।</strong> किसी भी हिस्से के रोल में स्वरों को चुनें, खिसकाएँ, लंबा करें, मिटाएँ, कॉपी करें, चिपकाएँ और दोहराएँ; दायाँ क्लिक करके खींचने से स्वर हटते और लौटते हैं। एक या दो बार की गिनती के बाद MIDI कीबोर्ड से रोल में रिकॉर्ड करें। हर हिस्से का अपना गेन और पैन है।","changelog.0cb3c4c9fd20":"<strong>रोल पर स्केल।</strong> रोल को गाने के स्केल पर या स्वरों वाली पंक्तियों पर समेटें; स्केल की पंक्तियाँ रंगी होती हैं और उससे बाहर का स्वर चिह्नित होता है।","changelog.0ef6f26c2429":"<strong>एक कुंजी से कॉर्ड।</strong> इन्हें चालू करें और एक कुंजी गाने के मूल स्वर में 3, 4 या 5 स्वरों का कॉर्ड बजाती है — माउस, कंप्यूटर कीबोर्ड या MIDI कीबोर्ड से।","changelog.d9cada2e85a6":"<strong>घोस्ट स्वर।</strong> जैसे-जैसे आप बनाते हैं, अगला स्वर या कॉर्ड हल्का-सा सुझाया जाता है; Tab उसे रखता है, एक क्लिक एक को रखता है, और कहीं और बनाने से सुझाव हट जाते हैं।","changelog.01aa58d9ab50":"<strong>बोल।</strong> धुन या प्रति-धुन के नीचे शब्द लिखें, अक्षर चिह्नित करके: वे शीट पर छपते हैं और गाए जाते समय जगमगाते हैं। हर पंक्ति के पास एक गिनती बताती है कि वह अपने बार में समाती है या नहीं। टाइप करते समय शब्द का बाकी हिस्सा सुझाया जाता है (Tab उसे ले लेता है) और ग़लत वर्तनी सुधारी जाती है, जब तक आप अपना शब्द रखने के लिए चेकमार्क न छुएँ या Shift+Tab न दबाएँ।","changelog.407e049442f6":"<strong>टेक, सपना 1–3 और फिर सपना।</strong> किसी भी हिस्से के तीन नए संस्करण, आपके मौजूदा के बगल में; एक चुनें और रख लें। किसी क्लासिक का फिर सपना उसे आपका अपना नया गाना बना देता है।","changelog.a2ae6ec40472":"<strong>सीड।</strong> हर रचना अपना सीड और हर हिस्से का टेक सीड दिखाती है, कॉपी के साथ। किसी गाने का सीड चिपकाएँ उसे फिर से बनाने के लिए, या किसी हिस्से का टेक सीड वह टेक वापस लाने के लिए।","changelog.7403cd98e6cb":"<strong>इतिहास।</strong> आपकी हर रचना में पीछे और आगे — हर एक ठीक वैसी ही लौटती है और रीस्टार्ट के बाद भी बनी रहती है। नई रचना कभी पुरानी को नहीं दोहराती।","changelog.3c500d42ebde":"<strong>क्लासिक सीखने के लिए हैं, ले जाने के लिए नहीं।</strong> किसी क्लासिक से सिर्फ़ उसके कॉर्ड बाहर जा सकते हैं। बनाया गया कोई गाना जिसकी धुन, प्रति-धुन या बेसलाइन किसी जानी-मानी धुन से मिलती हो, उस हिस्से को ऐप में ही रखता है और कारण बताता है।","changelog.ce67fa868077":"<strong>कीबोर्ड शॉर्टकट का डायलॉग।</strong> सभी शॉर्टकट देखने के लिए ? या ऊपरी पट्टी में उसकी कुंजी दबाएँ।","changelog.4ca2136708d7":"<strong>आपका प्रोजेक्ट याद रखता है।</strong> अपना DAW प्रोजेक्ट सहेजने पर गाना, उसके बदलाव, उसका मिक्स, उसके बोल, पियानो, दृश्य और क्रेडिट बने रहते हैं, और दोबारा खोलने पर सब कुछ वैसा ही लौट आता है।","changelog.e60841228886":"<strong>टाइमलाइन का प्रीव्यू बड़ा है</strong>, और उस पल गाए जा रहे शब्द दिखाता है।","changelog.1dca7b1d60db":"<span class=\"release__meta\"><span class=\"release__ver\">v0.3.0</span><time class=\"release__date\" datetime=\"2026-10-14\">2026-10-14</time></span>","changelog.d35d794c003e":"यथार्थवादी हाथ। अब Handscore के मंच पर हाथों की एक जोड़ी पियानो वैसे ही बजाती है जैसे कोई पियानोवादक बजाता — हर उंगली उस अंश के लिए चुनी हुई, स्केल पर अंगूठा नीचे से निकलता हुआ, और जब संगीत में हाथों को एक-दूसरे के पार जाना हो तो एक हाथ उठकर दूसरे के ऊपर से जाता हुआ। सीखने के लिए बासठ पब्लिक-डोमेन क्लासिक्स तैयार हैं, Mary Had a Little Lamb से लेकर Silent Night और The Star-Spangled Banner तक, और मंच के नीचे का ट्रांसपोर्ट आपको रोकने, पीछे करने, आगे करने या किसी भी पल तक खींचने देता है, और साथ-साथ आप नोट सुनते जाते हैं।","changelog.0390e4a43a0a":"<strong>कीबोर्ड पर यथार्थवादी हाथ।</strong> कलाई पर ख़त्म होने वाले दो हाथ चारों पियानो पर हर नोट बजाते हैं: हर उंगली वैसे ही चुनी हुई जैसे कोई पियानोवादक चुनता, स्केल पर अंगूठा नीचे से निकलता हुआ, चौड़े कॉर्ड्स तक पहुँच, अंगूठा करवट लेटा और हल्का मुड़ा हुआ, और पार करने के लिए एक हाथ उठकर दूसरे के ऊपर से जाता हुआ। जब कुछ नहीं बज रहा होता, तो वे कुंजियों पर तैयार टिके रहते हैं।","changelog.2c009dbabcfe":"<strong>नोट बजने से पहले ही तय फ़िंगरिंग।</strong> Handscore संगीत बजने से पहले तय करता है कि हर नोट कौन-सा हाथ बजाएगा और किस उंगली से, ताकि हाथ बाद में नहीं, बल्कि कुंजियों के नीचे जाते ही पहुँचें।","changelog.216f61cb53a3":"<strong>मोड चुनें।</strong> ऊपर बाईं ओर के बटन (या P) पर अब <em>मोड चुनें</em> लिखा है और यह आपके विकल्प श्रेणी के अनुसार खोलता है: वाद्य, क्लासिक गीत, अंश, और पाठ (बाद के संस्करण में आएँगे)।","changelog.44952a5f65fd":"<strong>सीखने के लिए बासठ क्लासिक्स।</strong> बच्चों के गीत, क्रिसमस गीत और कैरल, लोकगीत, स्पिरिचुअल और गान, क्लासिकल थीम और पियानो के लोकप्रिय गीत — Chopsticks, Jingle Bells, Silent Night, Ode to Joy, Für Elise, The Entertainer, The Star-Spangled Banner और भी बहुत कुछ — हर एक दो हाथों के लिए अरेंज किया गया, धुन दाएँ हाथ में और कॉर्ड्स बाएँ में। इन्हें शीर्षक या संगीतकार से खोजें। हर एक पब्लिक डोमेन में है।","changelog.d8fc29c977d3":"<strong>देखने के लिए अंश।</strong> एक स्केल, एक ii–V–I, एक आर्पेजियो और एक क्रॉसिंग, हर एक काम करते हाथों की एक झलक।","changelog.d0ff9a5e5f3f":"<strong>ट्रांसपोर्ट।</strong> मंच के नीचे चलाएँ, रोकें, बंद करें, पीछे करें और आगे करें, साथ में एक टाइमलाइन जो गीत का समय और उसके बार दिखाती है। उस पल के हाथ एक छोटे पूर्वावलोकन में देखने के लिए टाइमलाइन पर पॉइंटर ले जाएँ। उस पर खींचें, या पीछे करें या आगे करें को दबाए रखें, और आप हर वह नोट सुनते हैं जिससे आप गुज़रते हैं, किसी भी दिशा में।","changelog.197a823169eb":"<strong>एक मेट्रोनोम।</strong> इसे चालू करें, तो हर बीट पर एक क्लिक होता है, हर बार की पहली बीट ऊँची, जबकि इसके <em>M</em> के पास के बिंदु बीट दिखाते हैं।","changelog.f94e5b4b235f":"<strong>स्पेस चलाता और रोकता है।</strong>","changelog.dd397e7c80b2":"<strong>वाद्य बटन अब मोड चुनें है</strong>, और आप जो पियानो चुनते हैं वह वाद्यों में <em>वर्तमान</em> के रूप में चिह्नित होता है।","changelog.c59c86e0cd28":"<span class=\"release__meta\"><span class=\"release__ver\">v0.2.0</span><time class=\"release__date\" datetime=\"2026-10-14\">2026-10-14</time></span>","changelog.14c84d5c455f":"असली पियानो। Handscore के मंच पर अब चार पियानो हैं — एक कॉन्सर्ट ग्रैंड, एक पार्लर ग्रैंड, एक स्टूडियो अपराइट और एक पुराना सलून अपराइट — हर एक स्टूडियो जैसी रोशनी में और हर एक की अपनी आवाज़। किसी कुंजी पर क्लिक करें या अपने DAW से बजाएँ, और पियानो बज उठता है: कुंजी नीचे जाती है, उसका नाम धुंधला पड़ जाता है, और सस्टेन पेडल वह थामे रखता है जो आप छोड़ देते हैं। पियानो पिकर से आप कोई पियानो चुनने से पहले उसे सुन सकते हैं।","changelog.a8f76e859570":"<strong>चार असली पियानो।</strong> Grand Piano, Acoustic Piano, Upright Piano और Honky-Tonk Piano, हर एक का अपना आकार, फ़िनिश और आवाज़, दोनों थीम में।","changelog.6f544a8bd67f":"<strong>कुंजियाँ बजाएँ।</strong> किसी कुंजी को सुनने के लिए उस पर क्लिक करें, या कुंजियों पर से सरकाते हुए उन्हें एक-एक करके बजाएँ। आपके DAW से आने वाला MIDI पियानो बजाता है और उसकी कुंजियाँ हिलाता है, और सस्टेन पेडल आपके छोड़े हुए सुरों को तब तक थामे रखता है जब तक आप उससे पैर नहीं उठा लेते।","changelog.3f265130a08f":"<strong>पियानो जैसी चलने वाली कुंजियाँ।</strong> हर कुंजी अपने संतुलन बिंदु पर घूमते हुए नीचे जाती है, जितनी ज़ोर से बजाई जाए उतनी तेज़ी से, और नीचे रहने तक उसका नाम धुंधला रहता है और ऊपर उठने पर लौट आता है।","changelog.7fd2c1ed940d":"<strong>पियानो पिकर।</strong> ऊपर बाईं ओर का वाद्य बटन (या P) चार कार्ड खोलता है। <em>पूर्वावलोकन</em> पियानो बदले बिना उस पियानो पर एक छोटी धुन बजाता है; <em>चुनें</em> उसे मंच पर रख देता है, पिछले पियानो से क्रॉसफ़ेड करते हुए। आपकी पसंद आपके प्रोजेक्ट के साथ सहेजी जाती है।","changelog.72aa386a33ff":"<strong>आपके कंप्यूटर के अनुरूप गुणवत्ता।</strong> Handscore मापता है कि आपका कंप्यूटर मंच को कितनी तेज़ी से बनाता है, और उस गुणवत्ता पर टिक जाता है जिसे वह सहजता से बनाए रख सके।","changelog.1246fc93bca0":"ठीक किया गया","changelog.58e041aeca75":"<strong>व्यस्त कंप्यूटर पर भी कुंजियाँ पीछे नहीं रहतीं।</strong> जब कंप्यूटर धीरे बना रहा होता था, तब बजाई गई कुंजी ऊपर ही रह सकती थी, या उसका नाम आधा धुंधला रह सकता था; अब वह हमेशा वहीं रुकती है जहाँ आपके बजाने ने उसे छोड़ा।","changelog.e6eef73c000a":"<span class=\"release__meta\"><span class=\"release__ver\">v0.1.0</span><time class=\"release__date\" datetime=\"2026-10-12\">2026-10-12</time></span>","changelog.ff94e0b1d59f":"नींव। Freally Handscore CLAP और VST3 प्लगइन के रूप में और स्टैंडअलोन ऐप के रूप में लोड होता है, अपने लाइसेंस की स्वीकृति माँगता है, और अपने मंच पर खुलता है: असली पियानो के माप में 88 कुंजियों वाला कीबोर्ड, जिसकी हर कुंजी का नाम उसके सामने वाले हिस्से पर लिखा है। अभी कुछ भी जनरेट नहीं होता — वह असली पियानो और हाथों के साथ आएगा।","changelog.37cee751dc57":"<strong>प्लगइन और स्टैंडअलोन ऐप।</strong> Windows पर CLAP और VST3 (AU एक Mac पर बनाया जाता है), और एक स्टैंडअलोन ऐप जो अपने टाइटल बार और टास्कबार में Handscore का आइकन दिखाता है।","changelog.bf0d03d43bfd":"<strong>लाइसेंस अनुबंध सबसे पहले।</strong> जब तक आप सहमत नहीं होते, Handscore कुछ नहीं करता। आपका जवाब आपके कंप्यूटर पर रखा जाता है और हर खुली कॉपी द्वारा साझा किया जाता है, हर DAW में और स्टैंडअलोन ऐप में भी।","changelog.28bc52fb055e":"<strong>मंच।</strong> 88 कुंजियों वाला कीबोर्ड, A0 से C8 तक, असली पियानो के माप में, जो विंडो की पूरी चौड़ाई भरता है। हर कुंजी का नाम उसके सामने वाले हिस्से पर लिखा है — सफ़ेद कुंजियों पर गहरी स्याही में, काली कुंजियों पर सफ़ेद में — और कुंजी दबी रहने तक छिपा रहता है।","changelog.d51fdbedfc0e":"<strong>लाइट और डार्क।</strong> ऊपर दाईं ओर का स्विच; Handscore आपकी पसंद याद रखता है।","changelog.9e0609310c1a":"<strong>अठारह भाषाएँ।</strong> Handscore आपके सिस्टम की भाषा में शुरू होता है।","changelog.f1cf7c9dfaa8":"<strong>एक 3D व्यू जो बताता है कि वह कब नहीं बना सकता।</strong> WebGL 2 के बिना कोई विंडो कुछ भी न दिखाने के बजाय समझाती है कि इसे कैसे चालू करें।","changelog.0fe089d138d3":"<strong>क्रैश रखे जाते हैं, कभी भेजे नहीं जाते।</strong> अगर Handscore कभी अचानक रुक जाए, तो अगली बार शुरू होने के लिए एक छोटी रिपोर्ट आपके कंप्यूटर पर रखी जाती है। जब तक आप इसे रिपोर्ट करना नहीं चुनते, आपके कंप्यूटर से कुछ भी बाहर नहीं जाता।"};
